window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_024"]={"n":"许有壬","dyn":"元","poems":[{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其一","f":"五言古诗","c":["田塍晚独策，及此时雨晴。","东畦与西疃，泱泱流水声。","丰年已足欢，清风复多情。","归来藉草坐，浊酒还自倾。","不用浇磈磊，我怀无不平。"]},{"t":"琳宫词次安南王韵 其一","f":"七言绝句","c":["凉入帘帏夜色轻，瑶台添月更虚明。","一壶天地浑无迹，只有清风动竹声。"]},{"t":"荻港早行","f":"五言律诗","c":["水国宜秋晚，羁愁感岁华。","清霜醉枫叶，淡月隐芦花。","涨落高低路，川平远近沙。","炊烟青不断，山崦有人家。"]},{"t":"千秋岁","f":"曲","c":["青年诗好。","正坐声名早。","攀李杜，凌郊岛。","官惭才力弱，技悟文章小。","青镜里，朱颜不觉成衰老。","习气消除尽，惟酒娱昏晓。","思阮子，甘兵校。","因知身外事，何似尊前笑。","追往昔，中书已署阳城考。"]},{"t":"千秋岁 即席次可行见寿乐府韵","f":"曲","c":["谀人称好。","何似归来早。","营五亩，如三岛。","深杯江海浅，老眼乾坤小。","松竹在，肯教老圃秋容老。","方外多真趣，池上宜清晓。","随里社，游乡校。","逢场皆可乐，得句惟供笑。","吾有政，考功不校闲官考。"]},{"t":"六州歌头 次马明初韵书所见","f":"曲","c":["轩昂仙侣，风度似吾侪。","凡鸟辈，虽累百，总与台。","敢偕偕。","何处风丝客，昧平昔，恣豗突，形迹异，天壤隔，剧相排。","老眼浑如无见，云霄远，未便时乖。","笑蛛蝥肆螫，自丧亦多哉。","我出尘埃。","浩无涯。","有旁观者，同气类，公好恶，挺身来。","行不义，宜自毙，坐虺颓。","任奸回。","万事如翻手，吾方此，外形骸。","来汝鹤，吾有语，汝无哀。","谁遣乘轩烜赫，令此辈、眼不能开。","付恩仇一笑，漫且啄莓苔。","休面三槐。"]},{"t":"六州歌头 次明初为寿韵","f":"曲","c":["避贤解组，三见太行秋。","惭昼锦，犹远胜，敝貂裘。","玩沧洲。","霜水清如玉，穷霄壤，忘物我，恢障塞，无牖户，底绸缪。","自笑平生事业，知今日，颇善为谋。","有静中至乐，何处更天游。","已分淹留。","醉乡侯。","有江湖客，翰墨友，凌元白，压曹刘。","论文暇，陪杖屦，事觥筹。","共藏修。","世态谁能校，轻肮脏，重伊优。","吾有政、锄药圃，治瓜畴。","说与渔夫樵叟，既相好、岂但相犹。","任多言莫及，野渡有孤舟。","天地沙鸥。"]},{"t":"太常引","f":"曲","c":["二松如盖偃中庭。","向朱夏、作秋声。","摇影动疏棂。","掩映得、苔痕转青。","西清博士，西台御史，相对又双清。","咫尺到蓬瀛。","休认作、蓝田县丞。"]},{"t":"太常引","f":"曲","c":["年来诗笔尚能神。","但无柰、旧时贫。","天地一闲身。","且不在、青云后尘。","壶秋眸子，野人心事，相对好敷陈。","山酒正清醇。","要茅屋、朝朝是春。"]},{"t":"太常引","f":"曲","c":["四堤杨柳接松筠。","香破水芝新。","罗袜不生尘。","笑画里、凌波未真。","红云缥缈，清风萧飒，半醉岸鸟巾。","不是葛天民。","也做得、江湖散人。"]},{"t":"太常引","f":"曲","c":["道宫城市胜林塘。","松竹满、芰荷香。","煮酒出丹房。","记相见、匆匆一觞。","云萍飘忽，仙凡悬绝，翻手又殊乡。","何日漱余芳。","看华发、诗人许棠。"]},{"t":"太常引","f":"曲","c":["漱芳亭下小方塘。","清散水芝香。","回首翠成房。","忍不待、佳人奉觞。","紫垣朝暮，红尘车骑，遮断白云乡。","老我重寻芳。","又浑似、今年海棠。"]},{"t":"太常引","f":"曲","c":["云舒霞卷妆秾。","倒影水天红。","池转小台东。","又一种、娟娟玉容。","仙肌绰约，奇芳清远，浮动不晶宫。","一笑对衰翁。","好同赴、庐山社中。"]},{"t":"太常引","f":"曲","c":["幽人早起赴池亭。","看初日、照娉婷。","风盖露珠倾。","又胜似、前时雨声。","水沉乡里，锦云深处，双桧插天青。","一叶钓舟轻。","似野渡、无人自横。"]},{"t":"太常引","f":"曲","c":["诗成春草梦池塘。","相忆托玄香。","常记饮仙房。","笑一举、曾蒙十觞。","百年行止，几番离合，吾老且吾乡。","聊与领群芳。","渐开到、江头野棠。"]},{"t":"太常引","f":"曲","c":["荷盘蕉扇久无声。","笑祈祷、果难凭。","倚槛看云停。","问谁把、天瓢遽倾。","玄功不宰、太平有象，礧磈一时平。","老我问阴晴。","笑尚为、苍生有情。"]},{"t":"太常引 圭塘四首","f":"曲","c":["圭塘种藕已多时。","贴水晓星稀。","生意一朝回。","便万柄、红酣绿敧。","连宵骤雨，透空繁响，清绝不容诗。","对境写襟期。","要无愧、鸱夷子皮。"]},{"t":"太常引 次王居仁为寿韵","f":"曲","c":["进为卿相退为仙。","叹今古、少能全。","抛却祖生鞭。","且占取、烟霞洞天。","遥峰罨画，清流漱玉，故里好山川。","黄菊正鲜妍。","便沽酒、休论几千。"]},{"t":"太常引 武昌别墅","f":"曲","c":["胭脂山下老农家。","看雪树、翠交加。","香透小窗纱。","是昨夜、幽兰放花。","引泉浇树，破苔移菊，更种故侯瓜。","一笑有生涯。","但休叹、清霜鬓华。"]},{"t":"太常引 速可行治具","f":"曲","c":["忍寒搜句意何如。","正因我、腹焦枯。","茶灶火慵嘘。","高阳侣、元非姓卢。","佳章联叠，新醅寥落，飞梦绕兵厨。","新酿取来无。","要亲与、梅花饯途。"]},{"t":"太常引 速可行治具","f":"曲","c":["小斋潇洒颇宜贫。","清有竹、静无尘。","俗子不敲门。","只风月、烟霞是邻。","古瓶清雅，寒梅疏瘦，昨雨忽纷纷。","尚有一枝春。","快报与、南厅主人。"]},{"t":"太常引 登楼观柳","f":"曲","c":["云消春气恰和柔。","先到柳梢头。","数日不登楼。","笑青眼、窥人尚羞。","清明近也，老夫耄矣，其忍负欢游。","飞絮便生愁。","尽都变、浮萍去休。"]},{"t":"忆秦娥","f":"曲","c":["山花舞。","岩姿能笑禽能语。","禽能语。","百年心事，一犁春雨。","神仙护短多官府。","老夫只解为农圃。","为农圃。","乾坤休问，几番今古。"]},{"t":"忆秦娥","f":"曲","c":["山鸡唱。","少年中夜心悲壮。","心悲壮。","世间何事，不来眉上。","迷途未远奚惆怅。","五湖烟水春摇荡。","春摇荡。","谁知平地，拍天风浪。"]},{"t":"忆秦娥","f":"曲","c":["长安陌。","东风杨柳花如雪。","花如雪。","青条无数，为君攀折。","少年刚道轻离别。","临歧未信心如铁。","心如铁。","旧怀新恨，满梁残月。"]},{"t":"忆秦娥","f":"曲","c":["山瓢饮。","太空为幕云为枕。","云为枕。","松声万壑，月明风冷。","人生未老宜先省。","尘寰尽有清闲境。","清闲境。","孤云野鹤，杳无踪影。"]},{"t":"忆秦娥 和希孟张中丞韵","f":"曲","c":["山人笑。","人间不识山间妙。","山间妙。","岚光浮动，半江残照。","移文莫待山英校。","烟霞曾结三生好。","三生好。","白云深锁，葛洪丹灶。"]},{"t":"忆秦娥 送牛农师二首 其一","f":"曲","c":["春山碧。","诗成马上应相忆。","应相忆。","卢沟桥畔，晚云如织。","人生有别休多惜。","但悲后会知何日。","知何日。","暮云心绪，断鸿消息。"]},{"t":"木兰花慢","f":"曲","c":["问东来何处，控吴越，壮江淮。","爱十里萦纡，水云图画，鼓吹风雷。","回头下临无地，尽朱楼迢隔倚天开。","酒旆高悬别浦，绣帘低拂长桅。","疏狂常与世情乖。","胜地却须来。","漫怀古长歌，后庭花落，斜日潮回。","伤心旧时明月，照凄凉亡国恨无涯。","为问水边鸥鹭，人间几梦庭槐。"]},{"t":"木兰花慢","f":"曲","c":["渺西风天地，拂吟袖，出重城。","正秋满名园，松枯石润，竹瘦霜清。","扁舟采菱歌断，但一泓寒碧画桥平。","放眼奇观台上，太行飞入檐楹。","主人声利一毫轻。","爱客见高情。","便芡剥骊珠，莲分冰茧，酒注金瓶。","风流故家文献，况登高能赋有诸甥。","清露堂前好月，多应喜我留名。"]},{"t":"木兰花慢 次白公岩为寿韵","f":"曲","c":["记青年充赋，曾射策，对严宸。","便暮省朝台，才离管辖，又掌丝纶。","狂愚岂胜时用，幸扁舟归去早知津。","一任无钱使鬼，犹能有笔通神。","交游萍水百年身。","襟袂几回分。","正雪后花前，江东渭北，嗟我怀人。","澶渊召棠成颂，肯推扬余韵颂庄椿。","老矣甘心伏枥，天衢行看翔麟。"]},{"t":"木兰花慢 次韵马廷彦山居","f":"曲","c":["羡山人结屋，腰碧涧，面丹崖。","问桂有余香，槐多拥翠，谁种谁栽。","几年力田勤学，是庆源先世有人开。","乐地夏弦春诵，浮云暮省朝台。","半生奔走负山斋。","何地不尘埃。","叹老病才归，乡邻幸恕，不忍挤排。","白眉故人多事，似东门偏更道贤哉。","但有黄鸡白酒，老夫不倦频来。"]},{"t":"木兰花慢 次韵薛寿夫见寄","f":"曲","c":["笑予生多癖，非酒病，即书囚。","任世态翻腾，亥讹成豕，沉变为尤。","中条有亭无羔，论三休吾更早宜休。","方外青山故在，镜中白发新收。","天风锵佩下琼楼。","心事付东流。","向一壑云深，三年梦熟，八表神游。","渊明苦无多语，只高标千古邈难俦。","老子新衔自署，醉乡谈笑封侯。"]},{"t":"木兰花慢 和杜德常中秋韵","f":"曲","c":["叹流光如水，又分破，一年秋。","柰妒雨痴云，良宵佳节，不遂登楼。","山川满前图画，幸故乡无复有新愁。","风物催成老境，乾坤付与双眸。","几年京国苦淹留。","今得赋归休。","况天柱峰头，清辉好在，氛翳俱收。","身闲更逢全景，是腰钱骑鹤上扬州。","明日霜天红树，绝胜芦叶汀洲。"]},{"t":"木兰花慢 和陈彦章暮春即事韵","f":"曲","c":["问东君何意，来几日，便言归。","怅衰病襟怀，暄妍景物，正欲相依。","狂风不知人苦，遣万红千紫一时飞。","却见杨花才思，闲来萦绊晴晖。","可人应试纻罗衣。","底事雁书稀。","望故里关河，云林杳霭，烟水霏微。","多情已无聊赖，更扁舟孤负鳜鱼肥。","想见洹溪松竹，绿阴笼满苔矶。"]},{"t":"水龙吟","f":"曲","c":["五云飞出蓬莱，天香散满人间世。","龙翔凤翥，千龄一遇，明良庆会。","节钺重来，士民腾喜，山川增气。","想四方地远，九重心切，都要见、闾阎事。","寤寐天颜咫尺，袅秋风、一鞭归骑。","昔年勋业，乌台倚重，紫垣虚位。","自顾疏庸，资身无策，敢论经费。","但儒酸不改，作咸充赋，助和羹味。"]},{"t":"水龙吟","f":"曲","c":["洹堂半月三来，小庭日见添佳致。","苍稂疏瘦，黄葵高洁，玉簪清丽。","林影波光，新晴景物，嫩凉天气。","对溪山如此，田园归去，除诗酒、浑无事。","烂漫乡邻鸡黍，比当年、鼎烹加味。","古今都说，浮云春梦，功名富贵。","何事迷途，直临老境，才寻平地。","把尘寰休问，菊花行绽，请重来醉。"]},{"t":"水龙吟","f":"曲","c":["几年三到三台，往年不似今年好。","故人云集，远山屏列，蔚蓝清晓。","赵舞燕歌，一时奇绝，百壶倾倒。","对山川如昔，风烟不减，但人比、当时老。","放眼秋容无际，碧澄澄、雁天霜早。","曹瞒事业，悠悠斜日，茫茫衰草。","为问漳流，古来豪杰，浪淘多少。","有建安遗瓦，张吾笔阵，把奸雄扫。"]},{"t":"水龙吟","f":"曲","c":["结楼高倚晴空，人间何限思亲处。","白云谁遣，等闲出岫，悠悠来去。","本是无心，宁知下土，有人延伫。","怅芒烟衰草，九原难作，空目断、丘陵树。","见说大鹏变化，趁扶摇、又抟云路。","朱帘画栋，关山绵邈，梦魂良苦。","两字行藏，百年忠孝，致君荣祖。","待更驱屏翳，溥为霖雨，继商家傅。"]},{"t":"水龙吟","f":"曲","c":["历观今古名臣，求如公者人能几。","平生勋业，行其无事，一诚而已。","方信名言，臣门如市，臣心如水。","正乾坤清晏，飘然高蹈，非明哲、安能此。","太古岁寒松柏，尽春风、闹开桃李。","傅岩霖雨，苏门风月，无非天理。","莫讶求闲，从来老眼，阅人多矣。","待他年，凤诏九重重下，为苍生起。"]},{"t":"水龙吟 己丑中秋用韵","f":"曲","c":["可翁点检形骸，关心六事今犹可。","摩挲老眼，残编细读，小窗危坐。","信手挥毫，云烟撩乱，波涛掀簸。","笑蹒跚病足，登山不武，尚能踏、苔痕破。","便腹还堪容酒，齿牙攻、脯殽蔬果。","歌声到耳，宫商少误，肯教轻过。","馋口如门，丁宁告戒，欲须坚锁。","怕曲生徒众，众群然趋，入困风流我。"]},{"t":"水龙吟 次前韵","f":"曲","c":["此身就健宜闲，莫教七十才休致。","招谗贾怨，声名烜赫，文章雄丽。","三纪红尘，一簪华发，消磨豪气。","有清泉白石，实闻吾语，吾衰矣、毋多事。","世故真如嚼蜡，数年来、已知无味。","寻常有句，人为宰相，闲方是贵。","洹水秋清，无边风月，无穷天地。","看奋髯箕踞，苍苔浊酒，为青山醉。"]},{"t":"水龙吟 至顺癸酉九日秋与亭赋","f":"曲","c":["一亭飞出层霄，昔人似为登高办。","双眸千里，茫茫宇宙，滔滔江汉。","一片秋光，青山红树，断云斜雁。","想人生尘世，难逢开口，但酬节、何多叹。","细数年年今日，误清欢、半因羁宦。","迩来心事，无惭猿鹤，更齐鹏鴳。","华发新添，黄花任笑，乌纱频岸。","且一尊倾倒，不须醉后，把茱萸看。"]},{"t":"水龙吟 过黄河","f":"曲","c":["浊波浩浩东倾，今来古往无终极。","经天互地，滔滔流出，昆仑东北。","神浪狂飙，奔腾触裂，轰雷沃日。","看中原形胜，千年王气，雄壮势、隆今昔。","鼓枻茫茫万里，棹歌声、响凝空碧。","壮游汗漫，山川绵邈，飘飘吟迹。","我欲乘槎，直穷银汉，问津深入。","唤君平一笑，谁夸汉客，取支机石。"]},{"t":"水龙吟 寿静公右平章","f":"曲","c":["一生白浪红尘，得归才见乾坤阔。","三升无分，如何料理，文园消渴。","衰病禁持，不教杖履，经丘寻壑。","记平生怀抱，曾逢恶处，都不似、今年恶。","见说圭塘如旧，赖山英、好看猿鹤。","梦中斗室，蠹残图史，尘凝铛杓。","蟾桂香多，莫将长笛，等闲吹落。","问嫦娥，我辈何时还又，享清平乐。"]},{"t":"水龙吟 喜雨用郑彦章韵","f":"曲","c":["四郊禾稼如云，方惊数日甘霖好。","吾皇有德，老天能事，非因人祷。","一夜风雷，玄云撩乱，银河倾倒。","问田间消息，年年气象，更催得、秋成早。","压尽东华尘土，湛冰壶、九重清晓。","晴光渐放，瀛洲波定，御沟声小。","绿野春回，黄扉昼静，篆烟萦绕。","愿鱼羹有饭，避贤归去，向山林老。"]},{"t":"水龙吟 游三台","f":"曲","c":["半生人海风波，谤书盈箧从文致。","归来结构，且图跧伏，敢求华丽。","朝暮娱人，水声山色，柳阴花气。","笑彤闱紫闼，浮沉十载，更几载、成何事。","好是西成咫尺，秫田风、已飘香味。","安排小瓮，从今不怕，邻翁酒贵。","更筑诗坛，陪君游刃，周旋余地。","但有人来问，金銮旧话，便昏昏醉。"]},{"t":"水调歌头","f":"曲","c":["归欤正宜早，动也贵研几。","夜深山月飞出，何地不扬辉。","休说采山钓水，正尔切风批月，底用朵吾颐。","万事一尊酒，身外复何为。","笑年来，人与我，不相知。","投林已分垂翅，犹劝九天飞。","敢效归乡锦绣，且就盘铃傀儡，终日看儿嬉。","但恐子掀举，谁与话襟期。"]},{"t":"水调歌头 即席赠河南廉使高辛甫","f":"曲","c":["徒阳记同署，三十四年过。","朝台暮省踪迹，赢得鬓双皤。","相别又逾一纪，百岁都能几见，尘事日蹉跎。","今夕复何夕，旌节照山阿。","笑年来，洹水上，试渔蓑。","迂疏久厌城市，其柰故人何。","浩荡云山烟水，寥落晨星霜木，如子已无多。","邂逅一尊酒，忍负醉时歌。"]},{"t":"水调歌头 和郑彦章韵","f":"曲","c":["春来久无雨，都作艳阳天。","天公素念民事，其忍秽良田。","鞭起九渊浓睡，散作两间膏泽，生意发天然。","听得老农语，大有是今年。","玉堂深，金阙近，乱云烟。","乾坤放眼无际，何物不鲜妍。","休把圣功收敛，要使人心满慰，万事此为先。","我老归农好，宜买潞河船。"]},{"t":"水调歌头 胭脂井次汤碧山教授韵","f":"曲","c":["他山一卷石，何意效时妆。","天生偶然斑驳，兰麝不能香。","甃作陈家宫井，浇出后庭玉树，直使国俱亡。","故邑久眢废，陈迹草茫茫。","叹人间，才璇室，又阿房。","丽华鬒发如鉴，曾此笑相将。","一旦江山瓶坠，犹欲夫妻同穴，甚矣色成荒。","五色补天缺，万世仰娲皇。"]},{"t":"水调歌头 题萧独清山水胜处","f":"曲","c":["山水据全胜，消得独清人。","神仙定在何处，此处可寻真。","山有蓬莱气象，水有瀛洲风物，人是葛天民。","玩得紫芝老，吟尽碧桃春。","四时花，千日酒，一溪云。","回头下望浊世，无地不红尘。","忆昔乘轺江右，目断丹霞翠壁，底事走踆踆。","今日送君语，聊聊自移文。"]},{"t":"长相思","f":"曲","c":["梦扬州。","到扬州。","明月长街十二楼。","珠帘不上钩。","为谁忧。","为谁愁。","愁得春风人白头。","见花应自羞。"]},{"t":"兰陵王","f":"曲","c":["昆吾铁。","神物千年不灭。","时出匣、摇荡碧空，闪闪寒芒电光掣。","细看是巨阙。","三尺。","斜明隙月。","新丰旅，弹尔醉歌，也胜毛锥校平侧。","沉埋土花碧。","向坚石寒泉，重砺霜雪。","一天星斗昏无色。","因起舞为乐，崆峒试倚，魑魅胆寒石自裂。","免丰狱羁绁。","勋业。","几英杰。","是曾馘奸邪，腥渍余血。","今方四海边尘绝。","佩服处，闲伴金鱼宝玦。","只愁灵化，雷雨暗，水云国。"]},{"t":"玉烛新 题李伯瞻一香图次韵","f":"曲","c":["清风林下寺，爱三友联翩，世无能四。","凌波仙子香魂散，此地是谁招此。","万红千紫，惟矾弟梅兄二子。","堪共领岁晚高寒，来成花部新史。","佳人玉洁冰清，纵仿佛肌肤，异香难似。","醉吟无次。","花应笑，彼此消融渣滓。","春空雁字。","不带到、江南情思。","还自笑，今日相看，袁家有姊。"]},{"t":"玉漏迟 同前次张梦臣韵","f":"曲","c":["雪晴天似水。","风清月白，萧然三子。","天巧难名，镂玉锼冰无此。","却是同心异种，解敛聚、山林高致。","谁不喜。","花中隐德，人间真味。","邂逅粲者相逢，似琼佩霓旌，九霄飞坠。","移入铜瓶，付与野人凭几。","满意挼香嚼蕊，有浊酒、微吟相继。","休唤起。","明日此觥重洗。"]},{"t":"石州慢 次张凝道韵","f":"曲","c":["足趼尘嚣，目厌纷华，扰扰蜂蝶。","击壶未了长歌，又听阳关三叠。","平生湖海，可怜牢落新丰，蓬山回首烟霞隔。","鹏鴳不同天，任焦明蚊睫。","愁绝。","停杯为问羲娥，几度东生西灭。","俯仰金台，陈迹千年谁接。","天空秋老，倚阑南北悠悠，暮云汀树人长别。","想见苦吟诗，满吴江枫叶。"]},{"t":"石州慢 送牛农师赴石州学正","f":"曲","c":["少日襟期，不信儒冠，能把身误。","长歌拂袖南来，眼底云霄平步。","黄金散尽，三年流落京华，区区又上并州路。","官冷坐无毡，任齑盐朝暮。","今古。","男儿万里封侯，休叹云萍羁旅。","我亦苍黄，明日携书北去。","居庸关下，萧萧风振驼铃，酒醒梦觉君何处。","画出断肠时，满斜阳烟树。"]},{"t":"如梦令","f":"曲","c":["谁把清风领受。","寻得岁寒心友。","霜月玉亭亭，恰似老夫诗瘦。","诗瘦。","诗瘦。","无柰碧云怀旧。"]},{"t":"如梦令","f":"曲","c":["桃李东风不耐。","好在西山如黛。","杖策看山来，正尔青青相待。","无柰。","无柰。","却被暮云妨碍。"]},{"t":"如梦令","f":"曲","c":["墙角黄葵都谢。","开到玉簪花也。","老子恰知秋，风露一庭清夜。","潇洒。","潇洒。","高卧碧纱窗下。"]},{"t":"如梦令","f":"曲","c":["火榻只宜春早。","纸张不知天晓。","枕上问山童，门外雪深多少。","休扫。","休扫。","收拾老夫茶灶。"]},{"t":"如梦令","f":"曲","c":["昨夜庭梧陨翠。","诗思尤便爽气。","无事要生悲，可笑宋家多事。","衰矣。","衰矣。","但校邻翁酒味。"]},{"t":"如梦令","f":"曲","c":["门外雪花飘洒。","坐上乌丝方写。","秋露白泠泠，更着玉人亲把。","三雅。","三雅。","取醉莫论多寡。"]},{"t":"如梦令","f":"曲","c":["有泪绿窗偷洒。","有恨锦笺难写。","消瘦不胜春，玉骨都无一把。","风雅。","风雅。","正值文君新寡。"]},{"t":"如梦令","f":"曲","c":["老子风神清洒。","好句自然传写。","立雪赋梅花，更折绿条成把。","闲雅。","闲雅。","莫道吉人辞寡。"]},{"t":"如梦令","f":"曲","c":["岁暮天寒时节。","满意相看冰雪。","不遣野人归，谁慰此君清绝。","清绝。","清绝。","添上一方明月。"]},{"t":"如梦令","f":"曲","c":["一片苍苔凿破。","百折清泉分过。","长日午阴圆，自挈胡床来坐。","斯可。","斯可。","从此闲身属我。"]},{"t":"如梦令","f":"曲","c":["为问蕃厘道士。","今日琼花开未。","老子偶然闲，要向花间游戏。","游戏。","游戏。","莫待清阴满地。"]},{"t":"如梦令 次郭子敬韵四首","f":"曲","c":["三日琼瑶飞洒。","天巧岂容摹写。","佳客不曾来，有酒定从谁把。","文雅。","文雅。","应笑珉多玉寡。"]},{"t":"江城子","f":"曲","c":["柳梢烟重滴春娇。","傍天桥。","住兰桡。","吹暖香云，何处一声箫。","天上广寒宫阙近，金晃朗，翠岧峣。","谁家花外酒旗高。","故相招。","尽飘摇。","我正悠然，云水永今朝。","休道斜街风物好，才去此，便尘嚣。"]},{"t":"江城子 次韵","f":"曲","c":["懒于沙鸟拙于鸠。","为无求。","得无忧。","底事疏狂，却效子长游。","毕竟无求何用出，求不得，亦宜休。","西风真解酿羁愁。","试登楼。","望南州。","黄叶疏云，摇荡一川秋。","更被谁家多事笛，吹不尽，思悠悠。"]},{"t":"行香子 同李元镇晚酌张氏小阁","f":"曲","c":["璧月香云，小院重门。","办诗愁、多是黄昏。","梨花淡淡，柳絮纷纷。","对古铜炉，神品画，靓妆人。","半醉多羞，一笑欺春。","有丹青、描写难真。","秋波侧媚，云岫轻颦。","是蕊珠仙，巫峡女，洛川神。"]},{"t":"齐天乐 天津桥次韵","f":"曲","c":["深宫傅粉，江东主肥，鲜养成娇软。","北望中原，自分秦越，尽付马蹂车碾。","神州天远。","笑六代封疆，一毫无展。","更着荒淫，月明琼树照同辇。","长虹谁驾千尺，要等闲尽跨，人海深浅。","名袭东都，侯封违命，赢得兴亡流转。","年光冉冉，又匹马南来，片时宫苑。","独倚阑干，夕阳鸦万点。"]},{"t":"沁园春 临清舟中即席，次韩伯高见赠韵","f":"曲","c":["草木无情，不问寒喧，开时便开。","只黄花多事，偏怜隐逸，白头何补，愿避贤才。","老友相逢，清谈绝倒，休校刘郎去后栽。","尊中物，胜他年千里，漫寄寒梅。","神仙合住蓬莱。","柰老母思儿忍不回。","任耿庄槐老，休为痴梦，梅家酒熟，且浣愁怀。","渭北江东，暮云春树，何日扁舟更此来。","公知否，便连朝觞咏，能几徘徊。"]},{"t":"沁园春","f":"曲","c":["俯仰乾坤，傲睨羲皇，优游快哉。","看平湖秋碧，净随天去，乱峰烟翠，飞入窗来。","鸿鹄翱翔，云霄寥廓，斥鴳蓬蒿莫见猜。","门常闭，怕等闲踏破，满院苍苔。","人间暮省朝台。","柰鸟兔堂堂挽不回。","爱小轩月落，梦惊风竹，空江岁晚，诗到寒梅。","两鬓清霜，一襟豪气，举世相知独此杯。","京华客，问九街何处，堪避风埃。"]},{"t":"沁园春","f":"曲","c":["老子当年，壮志凌云，巍科起家。","被尘嚣沸耳，鏖成重听，簿书眯眼、攻作昏花。","天上归来，山中绝倒，部曲黄牛鼓吹蛙。","闲宫好，判园丁牧竖，一日三衙。","平生几度天涯。","恰舣住飘飘泛海槎。","向竹林苔径，时来教鹤，山泉石鼎，自为烹茶。","庭下花开，楼头雨霁，尽着春风笑鬓华。","功名事，问西山爽气，多少烟霞。"]},{"t":"沁园春","f":"曲","c":["采诗洹水，清秋兴来，不暇求工。","致行云流水，虽违高古，亦无浮丽，更有佳人。","韶音同韵，芝兰同气，笑高山□□□中。","宰相倡酬，余力判酒，政兼花事。","休教阮家三品，但身闲便。"]},{"t":"沁园春","f":"曲","c":["坎止流行，行止非人，何劳用心。","羡枝巢居士，泥涂轩冕，时斋老子，城市山林。","富贵何常，荣枯递转，惟有高名不陆沉。","他休问，只清风一榻，多少黄金。","神仙方外难寻。","更可笑牛山泪满襟。","且清尊素瑟，半庭花影，芒鞋竹枝，十里松阴。","归去成辞，闲居留赋，梁父安能抱膝吟。","迷途者，听云闲高唱，谁嗣鸿音。"]},{"t":"沁园春","f":"曲","c":["弱冠离家，浪走人间，馀三十年。","柰救时才短，虚尘政府，读书功少，深负经筵。","风月西清，冰霜柏署，一岁中间漫几迁。","君恩重，便不教覆餗，直许归田。","丰碑高表洹阡。","又飞上吴头万里船。","把家传图史，拂除尘蠹，旧栽松竹，收贮云烟。","大别嵯峨，鹄逢缥缈，尽在先生几案前。","闲人事，但登楼小酌，闭户高眠。"]},{"t":"沁园春","f":"曲","c":["天相吾家，箧笥无金，诗书有人。","看发挥胸臆，辞锋凛凛，薰陶气质，韦佩申申。","师友渊源，贤才衡鉴，胄馆光华近帝宸。","男儿事，便尽输心力，难报君亲。","读书第一当勤。","只孝弟书中是大伦。","况人生为学，百年在幼，田家得计，一岁惟春。","科占龙头，名高雁序，好与皇家作凤麟。","都休问，是地钟河岳，天应星辰。"]},{"t":"沁园春","f":"曲","c":["顶有丹砂，服具玄明，云胡作奴。","想风霜搏击，不如一鹗，云霄变化，复愧双凫。","尔雅无史，山经不志，多识惭予问学孤。","今知汝，肯自为卑下，甘事勤劬。","蟹奴鱼婢然乎。","笑多事文人善矫诬。","爱汝从仙侣，每能谦仰，日陪食饮，惟取残余。","赤壁飞来，云龙放去，守舍应门属眇躯。","无多语，似王家便了，有约休渝。"]},{"t":"沁园春","f":"曲","c":["四海之间，难弟劣兄，白头二人。","记昌期瑞旦，行年在卯，善门余庆，维岳生申。","科第佳名，祠宗优秩，常奉天香降紫宸。","身通贵，只贫安分定，老益书亲。","简编不负辛勤。","羡进德扬名迈等伦。","任家无厚积，融融度日，诗多好句，蔼蔼回春。","明月清风，交梨火枣，竹里行厨脯擘麟。","吾何事，但问花携酒，专竞芳辰。"]},{"t":"沁园春","f":"曲","c":["少日飞腾，湖海奇胸，风云壮图。","把人间远道，看为咫尺，眼前实地，认作虚无。","酾酒中天，振衣千仞，尘世烟霞有几区。","君山下，见洞庭清浅，欲问麻姑。","故吾只是今吾。","已深愧当年大丈夫。","怅川流不息，直如逝者，天风高举，更有谁欤。","鼎鼐何功，江山多幸，长铗归来食有鱼。","神仙事，笑临邛道士，还在洪都。"]},{"t":"沁园春","f":"曲","c":["有物庞然，乃牝而犁，山川舍诸。","为老饕营□，因疏黄稚，平心酬德，忍怠青刍。","方丈无功，万钱增害，茹饮方将笑穴居。","桃林媪，幸日输甘湩，香泛流酥。","老饕笑问长须。","汝今似挏官不是奴。","更题封谁调，聪明德祖，和浆且浣，消渴相如。","火候冲融，春膏浓结，常遣韦囊似瓠壶。","将军腹，问果谁相负，吾欲明书。"]},{"t":"沁园春 次王仲武为寿韵","f":"曲","c":["彼寿而康，雁自能鸣，樗还不材。","且光华老境，春风秋月、消磨旧梦，暮省朝台。","倚伏相寻，穷通素定，轩冕于人果傥来。","神仙远、有桃花流水，便到天台。","云林都是亲栽。","幸登览犹能矍铄哉。","但携琴载酒，时时游戏，逢山见竹，处处安排。","谏议无功，催科无政，烂醉何妨卧客怀。","承平日，看英才用世，多少台莱。"]},{"t":"沁园春 次张孟功韵","f":"曲","c":["击楫中流，跃马长途，今非向年。","叹故人万里，江东渭北，流光几度，雁后花前。","鬓影星星，人情落落，恰念苏家负郭田。","空惆怅，负清泉白石，布袜行缠。","壶中浩荡瑶天。","问清浊何须较圣贤。","想尘埃狂走，难逢一笑，扶摇直上，且任孤骞。","饭有鱼羹，储无甔石，何必千金学计然。","君知否，但东山丑妇，也自婵娟。"]},{"t":"沁园春 次班彦功韵","f":"曲","c":["旅食京华，蜀道天难，邯郸梦回。","笑白衣苍狗，悠悠无定，黄尘赤日，扰扰何为。","长铗休弹，瑶琴时鼓，倦鸟谁教强去来。","衡门下，幸良辰良友，同酒同诗。","功名少壮为期。","柰身外升沉自不知。","算人间难得，还丹大药，山中尽有，老树清溪。","蕙帐云空，石田苔满，应被山灵怪去迟。","春来也，向故园回首，归去休迷。"]},{"t":"沁园春 寿同馆虎贲百夫长邓仁甫","f":"曲","c":["十载炎方，同饮汉江，同为转蓬。","恨寻常会面，当年无分，三千余里，此地相逢。","宇宙英奇，幽并慷慨，肯事区区笔砚中。","男儿志，要长枪大剑，谈笑成功。","辕门醉卧秋风。","看落日旌旗掩映红。","爱朔云边雪，一声寒角，平沙细草，几点飞鸿。","湖海情怀，金兰气谊，莫惜琼杯到手空。","君知否，怕明朝回首，渭北江东。"]},{"t":"沁园春 送乡人高子翔次来韵","f":"曲","c":["放眼芜城，北尽淮堧，东驰海门。","叹故园遥隔，关山歧路，好怀深负，风月乾坤。","邂逅佳人，笑谈清致，所见而今胜所闻。","江湖乐，任提鹇絜鹭，翳凤骑麟。","世间富贵浮云。","也莫校箕山与渭滨。","想抱关击柝、心期贤圣，耕田凿井，上有华勋。","休道官卑，休嫌俸少，且喜诗成句句新。","君归矣，问故园桃李，几度逢春。"]},{"t":"念奴娇","f":"曲","c":["南鸿过尽，正龙沙岁晚，严凝时节。","朔吹翻空沙石走，一夜坤维冻裂。","宇宙茫茫，山川杳杳，千里飞阴雪。","停骖回顾，壮心未信如铁。","京国十月先春，杏桃无数，破暖应开彻。","此去佳游知不负，醉里雕鞍南陌。","粪火炉边，简书丛里，肯念飘零客。","故人欲问，此情正待君说。"]},{"t":"念奴娇 汴中见寄","f":"曲","c":["一壶天地，亘南交朔漠，东溟西极。","斫桂吴刚难措手，转见今宵挺特。","露轧冰轮，云归碧海，上下琼瑶色。","白虚光里，更无毫发间隔。","梦想洹上池台，五年放浪，延赏无虚席。","底事夷山丞节镇，扰扰尘埃朱墨。","杰句才悭，深杯量减，况敢论勋业。","嫦娥应道，老当归去时节。"]},{"t":"念奴娇 赋萤","f":"曲","c":["更阑人静，正满天晴露，半庭斜月。","时见飞萤三四点，树影依稀相隔。","暗地偷月，微形自照，冷焰明还灭。","有时分乱，残星流下天阙。","应念造物多情，翻腾变化，腐草还成物。","多少黄萎随土壤，争似超然飞越。","我正清贫，寒窗寂寞，赖尔成勋业。","案头乾死，也胜零落霜雪。"]},{"t":"金菊对芙蓉 宿程松壑月香亭次韵","f":"曲","c":["晓梦初回，余酲未解，月明犹挂疏桐。","在月香绝顶，稳驾天风。","乔松劲竹高寒地，还容得、几朵芙蓉。","霜空放眼、水痕褪碧，山色添浓。","休问衰老诗穷。","把烟岚夺取，也是豪雄。","问今来古往，谁异谁同。","老怀陶写惟丝竹，有捧觞、林下丰容。","傍人任笑，疏狂不减，我辈情钟。"]},{"t":"临江仙","f":"曲","c":["十日恶风三尺雪，繁霜又满人间。","梅花谁与问平安。","玉肌清似削，争柰许多寒。","梦绕琅璃江上路，竹篱茅舍青山。","莫教芳酒滞归鞍。","黄昏无限月，待我倚阑干。"]},{"t":"南乡子","f":"曲","c":["小隐远民廛。","草舍三间柳作椽。","围绕佳城才二顷，山田。","便觉胸中绰绰然。","世态自争妍。","老我壶觞业自专。","地阔天宽容醉舞，回旋。","又似偷闲学少年。"]},{"t":"南乡子","f":"曲","c":["暑室困蒸炊。","呼鹤前来听咏诗。","鹤告不餐空碌碌，随鸡。","诸仆无恩但有威。","云海夙相期。","忍使清斋十二时。","主者不才今遣汝，调饥。","骑去扬州定属谁。"]},{"t":"南乡子","f":"曲","c":["尘梦黍方炊。","白鹤空中漫诵诗。","饮啄适时争得似，山鸡。","敢效妖狐更假威。","曾与老仙期。","卫国遭逢彼一时。","千六百年才不食，无饥。","我欲推穷欠大谁。"]},{"t":"南乡子","f":"曲","c":["波漾石粼粼。","浮磬依稀类泗滨。","回首林虑千万丈，嶙峋。","不效修蛾一点颦。","幽讨日方亲。","林下何尝见一人。","便把清流都洗尽，缁尘。","领取羲皇以上春。"]},{"t":"南乡子","f":"曲","c":["沙砾不堪炊。","华表高歌乞食诗。","不为啄腥甘趁逐，群鸡。","为伴书痴老窦威。","万里在襟期。","会见青云奋迅时。","吐故纳新元有术，偏饥。","奉瘗佳铭却付谁。"]},{"t":"南乡子","f":"曲","c":["健笔挽银河。","公直銮坡我谏坡。","只好老来供一笑，呵呵。","喜怒从人愧国皤。","花月共婆娑。","劝饮随君学邵酡。","松菊有盟休冷落，哦歌。","我辈同年甚不多。"]},{"t":"南乡子","f":"曲","c":["乌鹊欲填河。","蝜蝂多持更上坡。","虫鸟无知徒自苦，谁呵。","恰似贪人少已皤。","市也好婆娑。","要染先生面色酡。","有口难言今只可，狂歌。","终岁陶陶不是多。"]},{"t":"南乡子","f":"曲","c":["山水绿相纡。","好个依山傍水居。","不是隆中高卧处，茅庐。","直挽岷峨入壮图。","匡世策全疏。","只合归来坐守株。","乡里小儿从笑我，非夫。","却胜携人共泛湖。"]},{"t":"南乡子 次可行韵二首 其二","f":"曲","c":["薄宦苦营营。","半世长亭复短亭。","一旦结茅当叠嶂，云屏。","朝暮阴晴几样青。","浊酒瓦盆盛。","农父无才却有情。","好雨知时公到此，安宁。","话到盆空月满庭。"]},{"t":"南乡子 和明初鹤饥韵四首","f":"曲","c":["淅米剑头炊。","枵腹雷鸣出险诗。","诗客眼高轻视鹤，如鸡。","终是鸡群有等威。","供饲不如期。","柰此瓶储告尽时。","也胜劈琴馋俗子，充饥。","穷饿相从更怨谁。"]},{"t":"南乡子 和欧阳玄之韵","f":"曲","c":["高论听悬河。","先知新诗问老坡。","手冷不甘寒气早，谁呵。","更被黄花笑鬓皤。","风竹乱婆娑。","老我衰颜藉酒酡。","佳节重逢真可赏，赓歌。","陶令壶觞旨且多。"]},{"t":"南乡子 醉书月香亭桂几","f":"曲","c":["老子分渔樵。","说着登山气更豪。","天外长江流不尽，迢迢。","脚底青云步渐高。","两手敢辞劳。","右有深杯左有螯。","我似渊明多一字，陶陶。","明日黄花笑二毛。"]},{"t":"南乡子 赠轧二弦胡琴高才甫","f":"曲","c":["锦瑟思华年。","底用嘈嘈五十弦。","两线清冰千万调，能传。","句句分明字字圆。","高艺擅华筵。","多少新声出自然。","更着赵娘歌宛转，相联。","消得诗人笔似椽。"]},{"t":"春从天上来 祝一斋大参寿","f":"曲","c":["自古英雄。","试倒指，谁能廊庙雍容。","相君此遇，风虎云龙。","光掩前后诸公。","正天开治运，□□力、启沃宸衷。","况平生，把诗书礼乐，烂入胸中。","当年侧闻先德，只一语唤起，万室春风。","桂树成丛。","棣华联萼，总是旧日阴功。","怪昨宵雪霁，烟光薄、生意浮空。","我来为寿，相朝何似，维岳维嵩。"]},{"t":"柳梢青","f":"曲","c":["窗对晴岚。","门临流水，坐阅归帆。","为口劳心，雪犹烧笋，霜便分柑。","酒香梅下茅庵。","就湖置、新鱼满篮。","梦记当年，此皆身享，好个江南。"]},{"t":"点绛唇 次吕叔泰韵","f":"曲","c":["云海茫茫，何人寻得春归处。","年年迟暮。","不逐春归去。","何日真归，历历江湖路。","舟横渡。","青山无数。","醉吸荷心露。"]},{"t":"点绛唇 病中偶成","f":"曲","c":["酒病诗愁，好春三月常孤负。","开门春暮。","新绿迷云树。","一片飞花，绾住游丝舞。","东风妒。","等闲吹去。","散乱随红雨。"]},{"t":"贺新郎","f":"曲","c":["陈迹空凫渚。","怅繁华、等闲一梦，便成今古。","佩玉鸣銮人如画，何处为云为雨。","只明月、还生春浦。","帝子当时无穷欲，奈浮云、回首浑非故。","天有意，肯轻许。","江湖襟带雄吴楚。","更翩翩、三王文采，丽章骈句。","一旦飞来韩家笔，才见龙翔凤舞。","漫千载、怀人延伫。","豪杰纷纷今谁在，笑世间、华屋争寒暑。","瀛海远，去无侣。"]},{"t":"贺新郎 次吕叔泰南城怀古","f":"曲","c":["故垒空如堵。","杳无踪、朝台暮榭，燕歌赵舞。","为问人间繁华梦，几度邯郸炊黍。","只燕子、春来秋去。","太液句陈何由辨，似咸阳、一炬成焦土。","兴与废，竟谁主。","满川芳草迷烟雨。","怅平生、楚骚心事，更堪羁旅。","野水芙蓉香寂寞，犹似当年怨女。","长啸罢、中天凝伫。","沧海桑田寻常事，附冥鸿、便欲飘飘举。","回首后，又千古。"]},{"t":"浣溪沙","f":"七言古诗","c":["老境闲门昼不开。","闲人庭院甚宜苔。","打门诗债任渠催。","千里有家频入梦，一春无酒可开怀。","心宽随处是蓬莱。"]},{"t":"浣溪沙","f":"七言古诗","c":["修黛横愁苦爱颦。","赪霞乱玉更宜嗔。","嗅香挼蕊柰何春。","织就回文难会意，写成离字亦伤神。","他年不及卷中人。"]},{"t":"浣溪沙 护圣李泠舟","f":"七言古诗","c":["花露浓沾桂棹香。","柳风轻拂葛衣凉。","放歌深入水云乡。","荷叶杯中倾绿醑，瓜皮船上载红妆。","都堂何似住溪堂。"]},{"t":"浣溪沙 游善应","f":"七言古诗","c":["崖上留题破紫烟。","岩前沦茗挹清泉。","烂游三日酒如川。","有水有山高士宅，无风无雨小春天。","人间真见地行仙。"]},{"t":"望月婆罗门引","f":"曲","c":["紫宸朝罢，东风吹到谪仙家。","貂裘抖擞尘沙。","一室窗明几净，人境独清华。","有息斋名画，殿帅高茶。","主人意佳。","道分手、即天涯。","何事相逢不饮，戚戚嗟嗟。","黄封旋拆，有鹅腊、鸡朐与兔羓。","公不饮、孤负梅花。"]},{"t":"望月婆罗门引","f":"曲","c":["人家十万，春风先到使君家。","天公更着芳华。","尽把楼台粉泽，琼树映横斜。","要歌宦白雪，暖借流霞。","吴姬赵娃。","乱银烛、影交加。","不放行云归去，敲碎红牙。","可怜杜老，肯飞送、江头只岸花。","争似我、夜醉长沙。"]},{"t":"清平乐","f":"曲","c":["赏梅观竹。","不暇镵黄独。","白玉吹香连碧玉。","富杀山人林谷。","几年行路艰难。","眼明今日重看。","便结岁寒心友，休教梦到槐安。"]},{"t":"清平乐","f":"曲","c":["天寒日暮。","百绕梅花树。","万斛清香藏不住。","都在一花开处。","可怜月堕霜飞。","不知疏影来时。","谁报云川老子，翠禽先在南枝。"]},{"t":"清平乐 和可行梅竹韵三首","f":"曲","c":["平生爱竹。","到处萦心曲。","一日相违人便俗。","栽满水边茅屋。","谁知岁晚空山。","佳人能慰荒寒。","莫论和羹结实，且看高节停鸾。"]},{"t":"清平乐 瓶梅","f":"曲","c":["胆瓶温水。","一握春如洗。","斗帐怯寒呼不起。","娇滴粉云香里。","谁教浅笑轻颦。","恰如镜里传神。","不用瑶天雪月，眼前琼树常新。"]},{"t":"清平乐 登北山阁","f":"曲","c":["钟山高处。","又结层楼住。","山自苍苍江自去。","万景一时收聚。","平生湖海诗豪。","更倾五斗香醪。","不信人间好句，不教驱入霜毫。"]},{"t":"清平乐 题郭思诚山居","f":"曲","c":["西岩仙老。","身在蓬莱岛。","竹月松云尘不到。","况有清风自扫。","霜溪浅碧摇沙。","烟村落照明霞。","说与门前鸥鹭，仙家又是渔家。"]},{"t":"清平乐 避暑神山咏桂","f":"曲","c":["堂前双桂。","云泼交加翠。","火老金柔花尚未。","且爱清阴满地。","秋风一旦花开。","天香吹散亭台。","却被花神见笑，先生未必能来。"]},{"t":"渔家傲","f":"曲","c":["窗影修篁摇翠葆。","墙阴幽径连芳草。","蓦地雨来荷叶闹。","香更好。","乱烟浮动红云岛。","稚柳千条丝袅袅。","柳边宜着兰舟小。","世态纷纷何足校。","收桂棹。","呜呜且和渔家傲。"]},{"t":"渔家傲","f":"曲","c":["露洗璇穹青杳杳。","年光红入滩头蓼。","翠盖撑烟吹半倒。","霜信早。","一奁寒影磨清晓。","早是轩扉尘不到。","好山更与供登眺。","酒债渐多诗债少。","翻水调。","西风几叠渔家傲。"]},{"t":"渔家傲","f":"曲","c":["落日崇台寒力悄。","登临恰似寻安道。","有竹何人能径造。","吾不诮。","相逢要遂掀髯笑。","双桧凌空龙夭矫。","有知定讶人枯槁。","珍重岁寒冰雪操。","君自宝。","老夫但和渔家傲。"]},{"t":"渔家傲 访华雪岩不遇","f":"曲","c":["水落寒林山骨瘦。","湘江风细波纹皱。","何处携琴何处酒。","惆怅久。","乱鸦啼断烟中柳。","茅屋萧萧连瓮牖。","半檐寒旭闲清昼。","归路梅花香满袖。","诗未就。","青山笑我云回首。"]},{"t":"渔家傲 歌圭塘四时四首","f":"曲","c":["冰尽泉香云缥缈。","韶华隐隐浮林杪。","酒在葫芦鱼在沼。","清昼悄。","好音时复来黄鸟。","管领风光心未老。","衰颜却怕清波照。","有酒可斟鱼可钓。","能事了。","东风一曲渔家傲。"]},{"t":"绿头鸭","f":"曲","c":["广寒宫。","秋期明日方中。","叹阴晴、自来无定，何如今夕从容。","棹兰舟、乱穿波月，斟玉斝、清带荷风。","身世难期，欢娱易失，名言千载记坡公。","公曾道，凉天佳月，何必限春冬。","况复有，西宾共载，仙季相从。","笑疏狂、兴来无尽，舣舟更策吟筇。","任诸君、班荆藉草，环四岸、度竹穿松。","飞上崇台，放开老眼，冰轮谁遣却朦胧。","多应是嫦娥见妒，胜事不教穷。","天知我，须臾风起，万里云空。"]},{"t":"绿头鸭 为牧庵寿","f":"曲","c":["论斯文，世谁方驾韩欧。","渺翩翩、旧家人物，一峰玉立高秋。","走蒲轮、銮坡再至，照藜杖、石室重绸。","要使吾元，典章文物，辉光什伯夏殷周。","君信否，千言乘醉，字字□雕锼。","侔堂阵，寄言渠辈，且避戈矛。","忆当年、江湖来往，月明太乙仙舟。","洒乌丝、芙蓉秋水，振宫锦、杜若芳洲。","鸾鹤赓歌，鱼龙迎舞，人间元自有天游。","傥来物视之毫许，岂足辱回头。","终焉计，匡庐深处，已办菟裘。"]},{"t":"菩萨蛮 宿造口用稼轩韵","f":"曲","c":["月明江阔天如水。","夜深残烛纵横泪。","底事不求安。","世间多好山。","一杯君且住。","万里人南去。","倡汝莫要予。","山寒无鹧鸪。"]},{"t":"菩萨蛮 寄中书诸公","f":"曲","c":["三司笑面靴纹皱。","鹾官憔悴非诗瘦。","红袖写乌丝。","谁曾梦见之。","淮盐真是白。","染得须成雪。","何处有神仙。","能教白复玄。"]},{"t":"菩萨蛮 寄都下友人","f":"曲","c":["凭高日望金台路。","黄沙尽处空烟树。","岁晚足萧疏。","雁声无夜无。","簿书临俗态。","人道儒酸在。","何以慰相思。","半年无好诗。"]},{"t":"摸鱼儿","f":"曲","c":["笑当年柏台兰省，四时风景孤负。","归来幸得身无事，底又匆匆朝暮。","心口语。","是传癖诗臞，常把芳辰误。","夜来风雨。","早练帨云飘，红衣霞卷，香滴翠杯露。","司花手，无限芳妍留住。","凝妆为我延伫。","姑仙绰约如冰雪，次第相从微步。","天不妒。","便失却东隅，尽有桑榆路。","人间尘土。","看太华峰头，花开十丈，吾老尚能去。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，尘凡皆与停务。","半生醉梦人间世，翻覆几回云雨。","归有渚。","似真到三山，缥缈红云屿。","忘怀笑语。","任白鹭惊飞，苍苔不扫，去此便无趣。","斜川路，宇宙茫茫何许。","绮园肯附诸吕。","悠然一见南山后，便觉世多尘句。","持此醑。","论心事中间，异姓还同谱。","迂疏好古。","因艺菊栽松，滋兰植蕙，荒了种瓜圃。"]},{"t":"摸鱼儿","f":"曲","c":["自箫韶九成来后，岐山犹是隆古。","嬴颠刘蹶相枕藉，几度狸号鳅舞。","堪笑处。","又蕞尔钟山，一霎神光吐。","鹤汀凫渚。","问吴德何徵，紫霄轻下，天意竟谁许。","江山好，老子狂今箕踞。","千年考信无据。","多情只有秦淮月，还照故宫焦土。","昏复曙。","漫寒暑悠悠，老尽梧桐树。","从今记取。","看阿阁成巢，朝阳应瑞，椽笔为君赋。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，田家小小成务。","一年清景君须记，大胜草烟花雨。","冰冱渚。","把一片玻璃，围护琼瑶屿。","钩帘独语。","是天富吾家，地输清供，种种出奇趣。","桑榆乐，造物而今已许。","一竿自惜归吕。","圭塘欸乃烟波曲，却作腐儒章句。","尊有醑。","是波若神汤，世与诗同谱。","谁能复古。","且池上观梅，炉中煨芋，灯下治书圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，散人不理他务。","柳栽近水先应绿，底用等闲霖雨。","遵北渚。","看双桧盘空，倒影摇烟屿。","千言万语。","只今日投簪，经年闭户，便自得天趣。","真男子，报国谁如张许。","论交仍负嵇吕。","我今但要闲陶写，幸免镂章雕句。","村瓮醑。","此真是，交梨火枣传家谱。","庭空树古。","有野鹤时来，衡门不锁，清彻地仙圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，年来于此承务。","凉台燠馆吾何有，聊芘一时风雨。","洲映渚。","向一片烟波，鼎峙嵯峨屿。","盘空硬语。","挽三峡词源，千军笔阵，不尽乐闲趣。","当年志，为国微躯曾许。","青云仍际干吕。","从知弱步难胜重，梦断九天胪句。","时饮醑。","趁四序栽花，缀作园池谱。","长歌吊古。","怅安得良田，茫茫万顷，种玉辟玄圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋载杨柳，田园忙胜官务。","放鱼种藕常无暇，移竹又当新雨。","由近渚。","驾一叶扁舟，时复还吾屿。","花香为语。","况心上无营，眼前多景，弦外有琴趣。","尊罍小，能费人间几许。","荷香惟欠仙吕。","天光云影清难写，尽日拈髭无句。","池作醑。","要醉上通明，传取钧天谱。","西山翠古。","任列壑争讥，攒峰竦诮，难及野人圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，眼中已办归务。","柳成修干莲成实，均沐老天恩雨。","怜小渚。","敢气象侵陵，海上神仙屿。","神仙有语。","任涓滴蹄涔，茫洋鲸浪，各自适归趣。","星星鬓，镜里衰容如许。","西风又动商吕。","九原宋玉悲何及，付与短歌长句。","瓢泛醑。","纵不到箕山，也是曾通谱。","由今视古。","看昼锦堂前，霜天老月，千载照韩圃。"]},{"t":"摸鱼儿","f":"曲","c":["问楼头几多烟景，长风千里吹送。","洞庭岛屿留残雪，依约玉龙飞动。","天故纵。","要老子南来，添得诗囊重。","遥山翠耸。","更淡淡斜阳，萧萧落木，感慨古今共。","人间世，何处祥麟威凤。","繁华一枕春梦。","江湖无限闲风月，待我往来吟弄。","君莫痛。","看起舞纷纷，踏破中宵瓮。","深杯自捧。","便唤起湘累，汨罗江上，沉醉是奇供。"]},{"t":"摸鱼儿","f":"曲","c":["笑人间衮圭何物，此花良贵天与。","倚阑瘦立亭亭玉，刻画一生清苦。","人有语。","道不出蓝田，岂是真才具。","山人告汝。","正蓬鬓萧疏，不胜冠冕，真者亦投去。","洹溪水，洗尽眼中尘土。","天葩静看齐吐。","冰壶凉月天如水，麈柄肯论夷甫。","翁醉舞。","任蕞尔寰区，共讶山中许。","搔风沐雨。","且受用清香，古今多少，富贵草头露。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，清风静扫尘务。","柳阴已见疏成密，又听绿荷敲雨。","鸥戏渚。","柰倏尔翻飞，飞过崔嵬屿。","形神自语。","岂世事相萦，机心未息，物我不同趣。","池亭小，收敛风烟来许。","渔歌何愧钟吕。","水纹瓦影相娱悦，高咏退之佳句。","荷酌醑。","有一曲沧浪，不犯人间谱。","悠悠振古。","问谁似吾侪，攻迂习澹，为水废场圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，归农未免多务。","一庭四序饶风景，且说夜来春雨。","香湿渚。","爱新树依稀，敷影连三屿。","黄鹂不语。","怕曲几圃蒲，坐忘方定，惊破静中趣。","功名事，却笑平生自许。","谁调阳律阴吕。","而今且向东君问，旧句岂如新句。","开腊醑。","要醉唤石湖，重缉寒梅谱。","荣枯自古。","趁九十韶华，六旬余力，终日醉吾圃。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，归来此是先务。","他乡故里都休校，旧雨不如今雨。","鸿在渚。","笑尔尚南飞，吾已安孤屿。","黄花解语。","道人老宜秋，身安耐酒，此正有真趣。","銮坡路，大手深惭燕许。","超腾又悖钟吕。","但求闲澹如元亮，却恨诗多奇句。","倾绿醑。","底须按，乐天池上霓裳谱。","休论往古。","有三日重阳，约君同醉，老子筑西圃。"]},{"t":"摸鱼儿","f":"曲","c":["笑山人木鸡心事，年来敛觜藏距。","幽花细草聊娱目，小圃更无闲土。","膏泽溥。","岂天为司晨，偏与钟奇古。","无人起舞。","对寂寂园池，萧萧风雨，竦立为谁怒。","三生梦，犹绕尸乡栖处。","昂然几欲掀举。","挼丹蹙锦头颅好，叶叶旧时毛羽。","天已许。","待海日升时，飞上桃都树。","人间凝伫。","看叫白东方，却来平地，千载不容腐。"]},{"t":"摸鱼儿","f":"曲","c":["买陂塘旋栽杨柳，闲官宜治闲务。","老天助我攻清淡，两月不遭泥雨。","规别渚。","更累土为山，留土分为屿。","乡人共语。","叹百岁堙芜，一朝疏辟，此去日成趣。","江湖愿，自是平生心许。","元英谁羡陈吕。","石渠细溜鸣琴筑，清似我家诗句。","杯引醑。","便收拾松风，写入丝桐谱。","区区学古。","愧窃禄无功，投闲有分，犹患不如圃。"]},{"t":"摸鱼儿 中都饯荀平叔都事赴大都","f":"曲","c":["正荒寒似逃空谷，佳人又话离别。","风低白草天无际，漠漠平沙如雪。","心欲折。","看落日飞鸿，一线明还灭。","长歌激烈。","把湖海襟期，关山风物，取次付弹铗。","毛锥子，千古钻研搜刔。","谁知更比鸠拙。","仲宣不作登楼赋，闲杀一天秋色。","珊佩玦。","羡公去鸣驺，醉上长安陌。","予怀转结。","怕紫塞寒深，碧云暮合，酒醒见明月。"]},{"t":"摸鱼儿 次明初为寿韵","f":"曲","c":["算驱驰三十余岁，只将光景虚度。","野云本是无心物，办得几多霖雨。","还自许。","量绵力粗才，犹可松筠主。","天方见与。","把村落溪山，风烟朝夕，着在最佳处。","青年志，万一容裨当宁。","何惭与哙为伍。","归来千仞冈头看，却笑瓮天飞舞。","方学圃。","要摘我园蔬，细和渊明句。","譊譊醉语。","道咫尺重阳，登高落帽，休竞汨罗渡。"]},{"t":"摸鱼儿 次郭子敬祭酒同赏牡丹韵","f":"曲","c":["记花王旧时名品，共传姚魏黄紫。","洛阳种植雄天下，何日移根来此。","青镜里，任淡抹浓妆，莫挽春衫比。","人间四美。","更天遣舒郎，等闲一赋，千载共心醉。","清平调，漫与东风料理。","繁华能扰天纪。","沉香亭上无人恨，流入锦江春水。","安故里。","又何似吾侪，聊复尊罍耳。","清歌且止。","怕檀板无知，多娇不耐，惊得彩云起。"]},{"t":"满江红 次汤碧山清溪","f":"曲","c":["木落霜清，水底见、金陵城郭。","都莫问、南朝兴废，人生哀乐。","载酒时时寻伴侣，倚阑处处皆楼阁。","对溪云、试放醉时狂，浑如昨。","沙洲外，轻鸥落。","风帘下，扁舟泊。","更寒波摇漾，绿蓑青箬。","为向九原江总道，繁华何似今凉薄。","怕素衣、京洛染缁尘，从新濯。"]},{"t":"满江红 次李沁州见寄韵","f":"曲","c":["徙倚危阑，爱四面、岚光翠湿。","回首见、疏云黄叶，远林平碛。","老眼都迷秋远近，壮游已遍天南北。","有一官、更比在家时，添幽寂。","人间世，天涯客。","唤李杜，招元白。","问凫因谁损，鹤因谁益。","有酒直须拼醉倒，古今长短嗟何极。","笑韩非、孤愤若为多，常填臆。"]},{"t":"满江红 次李沁州见寄韵","f":"曲","c":["一夜繁霜，便染得、乾坤澄寂。","秋满眼、萧萧云树，凄凄风日。","山色偏供羁旅恨，年光肯为英雄息。","只寒花、不减旧时香，天应惜。","官况薄，劳耕织。","诗律在，森戈戟。","更山城容我，清尊瑶瑟。","不是皇家劳结网，姓名底用人间识。","喜使君、时有一笺来，云烟湿。"]},{"t":"满江红 和郭子敬夏日村居韵","f":"曲","c":["一曲清溪，收拾尽、风声月色。","还自笑、六旬将近，数椽方葺。","已分封侯非燕颔，尽教有地争蜗角。","算人生、难得是清闲，吾今得。","离离黍，芃芃麦。","观此景，皆真乐。","更葵花未谢，藉花仍发。","烦剧只因诗有债，迂疏却喜门无客。","问小亭、盛暑不容人，今秋月。"]},{"t":"满庭芳","f":"曲","c":["槐院风清，藓阶尘净，日长镇掩衡门。","葛帷藤簟，石枕竹夫人。","不作南柯痴梦，要来往、月窟天根。","花阴转，闲关幽鸟，啼破一窗云。","起来盘膝坐，松风沸鼎，花雪浮春。","便洗除胸次，多少凝尘。","更喜秋原有秫，快准备、小瓮清尊。","东篱下，黄花香里，颠倒白纶巾。"]},{"t":"满庭芳","f":"曲","c":["学本迂疏，才非明哲，天恩偶听归田。","良辰美景，相遇更欣然。","细数人生行止，或城市、或在林泉。","都评过，忘形适意，惟是在尊前。","只今头尽白，但怜饮量，不似当年。","甚蘖痰媒渴，无事招愆。","时有亲朋来劝，学康节、微醉为贤。","先生笑偶，当乘兴，又作饮中仙。"]},{"t":"满庭芳 偕察士安马明初登荀和叔广思楼","f":"曲","c":["沙路无泥，柳风如水，嫩凉偏入吟鞍。","广思楼上，雨后看西山。","回首炎氛千丈，便长啸、跳出尘寰。","青天外，斜阳淡淡，倦鸟正飞还。","郊原秋色里，望穷霄壤，倚遍阑干。","问神仙何处，独占高寒。","楼下悠悠洹水，为底事、不暂休闲。","吾衰矣，休将旧手，遮日上长安。"]},{"t":"鹊桥仙","f":"曲","c":["雪松仙客，箕山道士。","来访思斋老子。","思斋何处未归来，想只在、翠红乡里。","风清月白，橙黄蟹紫。","一巷笙歌纷起。","良宵不遇负佳宾，都不念、人生有几。"]},{"t":"鹊桥仙","f":"曲","c":["心闲胜贵，身闲胜富。","已往而今始悟。","来言精力未宜闲，此俗子、便宜推去。","秋风鸡黍，春山杖屦。","尽是幽人乐处。","尽教须鬓雪飘萧，总不疑、衔杯琢句。"]},{"t":"鹊桥仙 寿可聪山平章","f":"曲","c":["胶身名爵。","醉心糟粕。","正可束之高阁。","庙堂谁信是行窝，更高似、尧夫一着。","胸中磅礴。","眼前寥廓。","与物元无城郭。","自从席末挹春风，觉二十年来尽错。"]},{"t":"鹊桥仙 宴胡安常侍御家","f":"曲","c":["清香华屋，黄葵红叶。","正是新凉时节。","文园多病不胜杯，孤负杀、一庭秋色。","珍殽纷错，玉醅芳烈。","醉倒江湖狂客。","凉天佳月即中秋，更有个、今年闰月。"]},{"t":"鹊桥仙 赠可行弟","f":"曲","c":["花香满院，花阴满地。","夜静月明风细。","南坡一室小如舟，都敛尽、山林清致。","竹帘半卷，柴门不闭。","好个暮春天气。","长安多少晓鸡声，管不到、江南春睡。"]},{"t":"鹊桥仙 赠相师周可山","f":"曲","c":["春秋七帙，江湖万里。","老子阅人多矣。","两朝名胜一囊诗，道浑似、当时袁李。","红尘陌上，白云堆里。","扰扰浮生行止。","我非燕颔虎头人，但诗圣、酒狂而已。"]},{"t":"蝶恋花","f":"曲","c":["九陌千门新雨后。","细染浓薰，满目春如绣。","恰信东君神妙手。","一宵绿遍官桥柳。","楼下兰舟楼上酒。","沙暖苹香，浑似来时候。","说与可人知信否。","伤春更比悲秋瘦。"]},{"t":"蝶恋花","f":"曲","c":["一片白云迷楚岫。","风卷青秧，迤逦波纹皱。","马上谁敲诗未就。","回头不觉双山堠。","渔父樵翁常邂逅。","问我何求，无事空奔走。","我固苍黄惭二叟。","少年有志还知否。"]},{"t":"蝶恋花","f":"曲","c":["万象森森天漠漠。","吹彻残更，声咽梅花角。","窗外月明无处着。","暗萤沾露随风落。","梦里诗成浑忘却。","起傍屏山，凉透纱幮薄。","静里悠然心自乐。","蓬山不用乘黄鹤。"]},{"t":"蝶恋花","f":"曲","c":["老子行年过耳顺。","蓬鬓萧疏，人道犹风韵。","领略风光元有分。","赏心又喜烧灯近。","薄雪初消寒欲尽。","词馆多闲，时得陪英俊。","莫讶连朝为酒困。","东君已是传花信。"]},{"t":"蝶恋花 以变白方赠朱亮卿","f":"曲","c":["闻道卿卿僝僽损。","花落深闺，无限伤春恨。","天上灵方吾不靳。","为君细染三生鬓。","镊白从今闲玉笋。","坐看丰姿，潦倒还髫龀。","洞里桃花应错认。","刘郎乃尔添风韵。"]},{"t":"踏莎行 赠相士","f":"曲","c":["黄鹤楼前，胭脂山上。","敲门有客来相访。","自言阅遍世间人，要观尘俗酸寒状。","关塞冰霜，江湖风浪。","归来幸得身无恙。","君言虽应我方惭，山中道士何劳相。"]},{"t":"鹧鸪天","f":"曲","c":["白发京华恋俸钱。","溪山游钓惜无缘。","老来恶兴凭诗遣，枕上才成一两联。","人自苦，月空圆。","衾绸如铁夜如年。","但稽子侄新文学，莫问宾朋岁几迁。"]},{"t":"鹧鸪天","f":"曲","c":["伏腊归宁已怆然。","天涯回首路三千。","倦游久赋王孙草，写恨应歌相府莲。","天也老，月空圆。","铁心难受夜如年。","麝煤闲杀春风手，想像颦蛾更可怜。"]},{"t":"鹧鸪天","f":"曲","c":["缕篆烟消月满帘。","青绫香减夜寒尖。","鹊桥谁驾银河渡，虬漏应将海水添。","天漠漠，恨厌厌。","不成怨梦睡空甜。","一春多少相思恨，瘦得腰肢分外纤。"]},{"t":"鹧鸪天","f":"曲","c":["心到忘机便是仙。","琴能得趣任无弦。","病多课子酬文债，田少从人借酒钱。","生盛世，遇今年。","雕虫存稿不求传。","有言难尽闲中乐，竹影花香白昼眠。"]},{"t":"鹧鸪天 次韵李沁州寄酒","f":"曲","c":["甘滑端能压蔗浆。","芳华初不藉山姜。","可怜太白分余沥，远与文园浣渴肠。","青琐闼，白云乡。","百年谁与校闲忙。","何如常对松岩老，万事悠悠付一觞。"]},{"t":"鹧鸪天 次韵李沁州寄酒","f":"曲","c":["滴困檀槽碎玉声。","青州合换沁州名。","高风未论陶元亮，豪气应吞阮步兵。","明老眼，慰浮生。","人间势利一毫轻。","羁愁如海都消尽，细和清歌带月倾。"]},{"t":"董仲达送予至湘阴别后顺风比晚行三百里怅然有怀作二绝付其仆之远送者持归 其一","f":"七言绝句","c":["吾子才华我最知，鬓毛回首各成丝。","汨罗江上一杯酒，萍水相逢又几时。"]},{"t":"董仲达送予至湘阴别后顺风比晚行三百里怅然有怀作二绝付其仆之远送者持归 其二","f":"七言绝句","c":["江蓠杜若满汀洲，骚国春来亦可愁。","一日顺风三百里，故人何处望予舟。"]},{"t":"无题","f":"七言绝句","c":["去年曾约牡丹开，同向花前把一杯。","今日花开人不见，对花无语却归来。"]},{"t":"原功题马宣使墨兰二幅后云寄予一笑因次韵书其侧且寄原功 其一","f":"七言绝句","c":["畹香连水水连天，人到湘皋骨已仙。","簿领如山空看画，江南秋色正清妍。"]},{"t":"原功题马宣使墨兰二幅后云寄予一笑因次韵书其侧且寄原功 其二","f":"七言绝句","c":["秋兰香里翰林家，只寄新诗不寄花。","应笑尘缨恋京国，岂知心在楚天涯。"]},{"t":"题姑射乘龙图","f":"七言绝句","c":["姑射仙人昔住山，乘龙飞去几时还。","只知尧舜如陶铸，不道声名堕世间。"]},{"t":"题三教啜醋图","f":"七言绝句","c":["吾儒风味格坚顽，二氏而今亦慕酸。","涓滴沾濡已如此，鼻容三斗故应难。"]},{"t":"贡院陪诸公夜话俄闻晓钟","f":"七言绝句","c":["烛花簌簌褪春红，睡思消磨语笑浓。","底事东风败人意，半天吹响五更钟。"]},{"t":"催诸公考卷","f":"七言绝句","c":["添烛须教夜达晨，继茶莫遣睡欺人。","城南桃李城东柳，政好联镳管领春。"]},{"t":"雄飞和诗未至以二口号速之 其一","f":"七言绝句","c":["骚坛纪律素严明，一帜撝风到处赢。","何事而今苦悭吝，有人乘夜欲登城。"]},{"t":"雄飞和诗未至以二口号速之 其二","f":"七言绝句","c":["两厅形迹马牛风，尽日相望杳霭中。","恰似蓬山三万里，怀人何处觅诗筒。"]},{"t":"何国器以精艺受知出而徵入者数矣出守江阴尚虑其不果行也书以赠之","f":"七言绝句","c":["华发萧萧旧秘书，木天图籍几勤劬。","莫教作郡江南去，天子时时幸石渠。"]},{"t":"过街塔原功名之曰雪窦又谓之名利关窦言其状关言其实也过之有感赋二口号 其一","f":"七言绝句","c":["来往憧憧急欲飞，此关参透古来稀。","老夫今日出关去，却是罢参真欲归。"]},{"t":"过街塔原功名之曰雪窦又谓之名利关窦言其状关言其实也过之有感赋二口号 其二","f":"七言绝句","c":["石城琼璧耸浮屠，一窍开通作要途。","为问几人能不窦，更从窦外觅江湖。"]},{"t":"岁晚喜晴","f":"七言绝句","c":["穷冬长路遽踆踆，风景弥旬暖似春。","造物见怜知有为，平生真是负暄人。"]},{"t":"车中戏作","f":"七言绝句","c":["不是车中有布乎，亦非客子事狂图。","却须侧挂一壶酒，道路荒凉无处沽。"]},{"t":"赠胡谦牧","f":"七言绝句","c":["寻常公署复朝参，会面何由一接谈。","却是老天相补报，直教联辔过燕南。"]},{"t":"独乐台用眠分黄犊草坐占白鸥沙为韵分赋得首尾二字 其一","f":"七言绝句","c":["疏慵闭户事高眠，几负郊原雨后天。","今日野心收不定，马家庄上好林泉。"]},{"t":"独乐台用眠分黄犊草坐占白鸥沙为韵分赋得首尾二字 其二","f":"七言绝句","c":["溅溅流水抱村斜，半入蔬畦半沤麻。","故里溪山足风物，慎毋重踏一堤沙。"]},{"t":"题仇公度总管首阳采薇图","f":"七言绝句","c":["史迁怨气因舒泄，吏部雄文痛发挥。","尽美未能兼尽善，益知周粟不如薇。"]},{"t":"吴道子周处磨剑图","f":"七言绝句","c":["长蛟猛虎不难屠，大勇其惟改过乎。","抛却步光为善士，方知自砺有工夫。"]},{"t":"范宽积雪图","f":"七言绝句","c":["冈峦楼阁斗清妍，一段空明水玉天。","不到阆城东向望，范家神妙若为传。"]},{"t":"薛思孝梦菊堂","f":"七言绝句","c":["华胥乡里有东篱，冉冉寒香步步迷。","政尔神交陶靖节，月斜霜落忽闻鸡。"]},{"t":"题明道赞后","f":"七言绝句","c":["圣远经残道晦蒙，茫茫千四百年中。","墓头两字形容尽，未可寻常议潞公。"]},{"t":"七贤过寒林图为蔡仲谦运使作","f":"七言绝句","c":["竹林陈迹已无稽，作者千年复有谁。","榾柮炉边不安坐，天寒日暮欲何之。"]},{"t":"温子昂画天王","f":"七言绝句","c":["万年麟史著尊称，底事空门妄欲争。","尺许断缣何足咎，古来多少盗虚名。"]},{"t":"李将军画马用班彦功韵","f":"七言绝句","c":["真龙幻出笑谈间，想像初离十二闲。","只恐风雷终变化，九天飞去几时还。"]},{"t":"寄李仲舒二首 其一","f":"七言绝句","c":["东门暂别已伤神，驿骑何堪又海门。","明日洹溪桃李下，春风谁与共清尊。"]},{"t":"寄李仲舒二首 其二","f":"七言绝句","c":["水曹清贵治吴邦，更有风烟助锦囊。","后夜吴松江上月，多应移照柏台霜。"]},{"t":"题崔鉴泉署丞作春山隐秀扇面","f":"七言绝句","c":["半生给事五云间，惯作蓬壶富贵仙。","移入月轮收不住，光风浮出翠孱颜。"]},{"t":"米元章临欧阳询帖","f":"七言绝句","c":["米家神俊不可遏，时学欧阳险劲书。","只道叔敖无少异，岂知优态未能除。"]},{"t":"高宗临王羲之七月帖","f":"七言绝句","c":["帝王言道不言书，况复时丁板荡馀。","偶效右军书七月，中原王业定何如。"]},{"t":"王右军屏风帖宣和所收","f":"七言绝句","c":["鼠须茧纸久消磨，谁信王书世不多。","片楮多应有神护，永和流播到宣和。"]},{"t":"高房山青山白云图为蔡仲谦运使赋","f":"七言绝句","c":["房山人品素高贤，流出天机肺腑间。","一片冰纨才数尺，几重云树几重山。"]},{"t":"再用鲜于伯机郭安道韵题房山画二首 其一","f":"七言绝句","c":["乱云斜日远冥濛，樵径萦纡一线通。","可笑无根满林树，春风才发又秋风。"]},{"t":"再用鲜于伯机郭安道韵题房山画二首 其二","f":"七言绝句","c":["杳杳层楼出半山，森森寒木护重关。","白云不去为霖雨，要与青山一样閒。"]},{"t":"题李师孟嵩云堂","f":"七言绝句","c":["极天终古翠巍巍，能聚阴阳赞化机。","寄与降神申甫辈，出为霖雨莫忘归。"]},{"t":"甲申元日春帖","f":"七言绝句","c":["雪消春意便暄妍，静看天机善斡旋。","试笔鲸川记风景，青天白日甲申年。"]},{"t":"题群鱼图","f":"七言绝句","c":["名品虽殊乐意均，藻香蒲软一湖春。","莫言惠子非知者，犹胜临渊羡汝人。"]},{"t":"苏彦良西野堂四绝 其一","f":"七言绝句","c":["春云护雪未全消，老柏垂冰冷不摇。","雁柱十三弦上月，酒阑香烬可怜宵。"]},{"t":"苏彦良西野堂四绝 其二","f":"七言绝句","c":["玳筵红袖不知寒，春在歌喉暖响间。","我辈年来要陶写，好将西野作东山。"]},{"t":"苏彦良西野堂","f":"七言绝句","c":["苍苔满径树连村，中有幽人屐齿痕。","此去客来宜定约，无诗无酒不开门。"]},{"t":"苏彦良西野堂四绝 其四","f":"七言绝句","c":["筑堂西野事西畴，桃杏才春麦又秋。","慎勿下堂东向望，禺商毫末拂牙筹。"]},{"t":"安平孙茂实九十八不衰诸公有诗贺其高年耆德","f":"七言绝句","c":["九十八年犹矍铄，百千万事任浮沈。","郊原杖屦亲朋酒，此是期颐未了心。"]},{"t":"题对镜写真图用滕玉霄韵","f":"七言绝句","c":["镜中几上共三人，为问先生孰是真。","自古圣贤皆不死，楮生何足托吾身。"]},{"t":"题千叶桃图","f":"七言绝句","c":["五出凡花一扫空，万重千叠裹春风。","连昌有竹堪为侣，底事墙头簌簌红。"]},{"t":"败荷鹭鸶扇面","f":"七言绝句","c":["苇折荷枯水有声，野塘斜日影伶俜。","鹓鸾班里忽飞去，点破西山一段青。"]},{"t":"题和叔扇头时坐登瀛楼","f":"七言绝句","c":["楼居高出白云间，不为求仙只为山。","领取烟岚无限景，天教吾与子俱閒。"]},{"t":"天宁方丈题和叔扇头","f":"七言绝句","c":["凉飙深殿度飕飕，老柏疏篁已报秋。","弱水波涛三万里，人间自有小瀛洲。"]},{"t":"陪明初行独乐台溪边得口号","f":"七言绝句","c":["寒波清浅带霜流，不到溪边不见秋。","叠嶂层崖三百转，树梢擎出月如钩。"]},{"t":"次白公严韵谢其寄酒与柑","f":"七言绝句","c":["任城绿醑侑黄柑，远寄山中岂所堪。","香雾噀人醒易解，不教飞梦到江南。"]},{"t":"题弄花香满衣图","f":"七言绝句","c":["冰绡桂襡缕金裙，浮动红芳乱綵云。","捲却六铢春沁骨，荀郎无复事炉熏。"]},{"t":"理宗书金丹诗 其一","f":"七言绝句","c":["常笑秦皇与汉皇，一生徒梦白云乡。","东南蕞尔垂亡国，犹说金丹事渺茫。"]},{"t":"理宗书金丹诗 其二 杜子美骑驴醉归图","f":"七言绝句","c":["田翁招饮不须沽，时事多忧一醉除。","天子乘骡蜀山险，浣花溪上分骑驴。"]},{"t":"理宗书金丹诗 其三 竹","f":"七言绝句","c":["玉立萧森几百竿，阴晴风雨各平安。","石兄节操不可转，宜与此君同岁寒。"]},{"t":"理宗书金丹诗 其四 虎","f":"七言绝句","c":["画虎不成常类狗，伊谁画狗却如狮。","世方取貌不求实，猛兽满山知不知。"]},{"t":"城楼暮霭 其一","f":"七言绝句","c":["楼上烟霏暝欲无，楼前车马正驰驱。","幽人不为晨昏迫，只看天然水墨图。"]},{"t":"城楼暮霭 其二 杏苑初春","f":"七言绝句","c":["玄都道士不栽桃，却爱生红闹树梢。","此去东风吹不散，仙家自有凤麟胶。"]},{"t":"城楼暮霭 其三 灞莲香雨","f":"七言绝句","c":["纷纷毂击复肩摩，有此清涟万柄荷。","沈水香中宜早赏，秋声不似雨声多。"]},{"t":"城楼暮霭 其四 洞阳午棋","f":"七言绝句","c":["琳宫寥阒子声频，树影初圆局几新。","门外茫茫名利海，可怜柯烂竟无人。"]},{"t":"城楼暮霭 其五 西圃晚眺","f":"七言绝句","c":["秋容淡淡映疏云，聊向苍苔散屐痕。","欲采紫芝心万里，斜阳尽处是昆崙。"]},{"t":"城楼暮霭 其六 延翠秋晴","f":"七言绝句","c":["霜清水落静无埃，邀得西山入座来。","爽气已供朝拄笏，烟光更助暮衔杯。"]},{"t":"城楼暮霭 其七 女墙积雪","f":"七言绝句","c":["千雉琼瑶琢不开，隐然凹凸混皑皑。","皇州寒尽春如海，不似秦淮月过来。"]},{"t":"城楼暮霭 其八 寒林噪鸦","f":"七言绝句","c":["树梢斜日下迟迟，啼破荒烟㨂一枝。","不为上林无著处，寒林宜画更宜诗。"]},{"t":"调赵子期二首 其一","f":"七言绝句","c":["玉堂学士日攻文，不识郊原有好春。","得见杏花千百树，却因东郭送行人。"]},{"t":"调赵子期二首 其二","f":"七言绝句","c":["春来频约赵崇文，同避红尘踏暖云。","底事相逢却归去，杏花今日雪纷纷。"]},{"t":"题经筵安仝译史新刻千文赐本二首 其一","f":"七言绝句","c":["芸阁风清昼景迟，楮生毛颖侍多时。","吾皇游艺超今古，能事犹推智永师。"]},{"t":"题经筵安仝译史新刻千文赐本二首 其二","f":"七言绝句","c":["隋僧变灭等浮云，七十三行墨尚新。","阁本重翻铁门字，圣恩均到石渠人。"]},{"t":"题赵仲穆二马图 其一","f":"七言绝句","c":["曹韩遗迹已无多，松雪堂中见小坡。","珍重双龙莫飞去，人间铜式久消磨。"]},{"t":"题赵仲穆二马图 其二","f":"七言绝句","c":["房星沦彩渥洼竭，神物谁令画得成。","幸自天闲异虞□，忍教立仗不教鸣。"]},{"t":"题爱莲图用卷中鲁子翚韵二首 其一","f":"七言绝句","c":["光风霁月不可见，奔轶谁能继绝尘。","看取芙渠菂中薏，一番花发一图新。"]},{"t":"题爱莲图用卷中鲁子翚韵二首 其二","f":"七言绝句","c":["昭昭无极发天倪，底事之人路尚迷。","但使爱莲知所爱，世间何水不濂溪。"]},{"t":"题段吉甫助教武夷山图","f":"七言绝句","c":["千崖楼阁湿青红，一水盘回万壑通。","不为风烟有佳色，紫阳道气在山中。"]},{"t":"题单父宋希贤孝友诗卷","f":"七言绝句","c":["家贫身壮赘它门，有志浑如不赘人。","致乐致哀终子职，肯教秦法变彝伦。"]},{"t":"和神保钦之御史监试上京韵四首 其一","f":"七言绝句","c":["蹛林云雾护皇州，贝阙珠宫远似浮。","骢马归时人尽道，槐花开遍上林秋。"]},{"t":"和神保钦之御史监试上京韵四首 其二","f":"七言绝句","c":["滦水天家第一州，赤霄楼观紫烟浮。","因君记我昔此役，二十五番鸿雁秋。"]},{"t":"和神保钦之御史监试上京韵四首 其三","f":"七言绝句","c":["茫茫九点认齐州，大地如舟日夜浮。","龙虎台前新雨露，人间无此一天秋。"]},{"t":"和神保钦之御史监试上京韵四首 其四","f":"七言绝句","c":["醉眼曾空十二州，肯随人海共沈浮。","白头不用悲陈迹，木落霜清恰见秋。"]},{"t":"次巴克实彦卿雪中见示韵六首 其一","f":"七言绝句","c":["曚昽晓雾勒晨光，一样隆寒两月强。","欲和阳春呵冻砚，老夫持酒手犹僵。"]},{"t":"次巴克实彦卿雪中见示韵六首 其二","f":"七言绝句","c":["残雪虚窗夜有光，小斋清话意差强。","江南不寄梅花信，冷眼空看万水僵。"]},{"t":"次巴克实彦卿雪中见示韵六首 其三","f":"七言绝句","c":["东华射圃接天光，日日趋朝看晚强。","白发无能思补报，肯矜霜简几人僵。"]},{"t":"次巴克实彦卿雪中见示韵六首 其四","f":"七言绝句","c":["曾向骚坛接步光，将虽云老尚兵强。","莫言白战无英气，百足商蚷死不僵。"]},{"t":"次巴克实彦卿雪中见示韵六首 其五","f":"七言绝句","c":["晃朗江天炫日光，玉峰寒立斗高强。","自然有类昌黎笔，籍湜谁能走且僵。"]},{"t":"次巴克实彦卿雪中见示韵六首 其六","f":"七言绝句","c":["谁因景物竞流光，为学终身贵自强。","身立程家门下雪，从知寒气岂能僵。"]},{"t":"题岳阳楼图","f":"七言绝句","c":["忆昔登楼得句新，君山湘水共无尘。","而今见画思陈迹，深愧先忧后乐人。"]},{"t":"题滕王阁图","f":"七言绝句","c":["赐麻帝子久无闻，南浦西山自雨云。","遂使阁名传不朽，却因骈俪一篇文。"]},{"t":"谢淮东廉司经历马九霄画鹤见寄","f":"七言绝句","c":["骑上扬州不可招，一朝蜕影入冰绡。","凡夫岂敢留仙骥，却遣衔书赴九霄。"]},{"t":"题澹然平章鹞子","f":"七言绝句","c":["西风凉动早秋天，小雀何须畏杜宣。","见说微形多变化，好为布谷莫为鹯。"]},{"t":"题明初扇","f":"七言绝句","c":["广文庭下草青青，绛帐秋风一夕生。","诗思莫教乡思搅，江湖华发我同声。"]},{"t":"中秋可行招饮因诵东坡明月明年何处看之句座中请明初可行各和其韵予得二首皆用三叠体仍命祯赋 其一","f":"七言绝句","c":["夜来风雨不成寒，似念幽人在考槃。","老夫老态月应道，明镜明朝君自看。"]},{"t":"中秋可行招饮因诵东坡明月明年何处看之句座中请明初可行各和其韵予得二首皆用三叠体仍命祯赋 其二","f":"七言绝句","c":["夜深风露恰知寒，风在絺衣月在盘。","一樽浊酒对明月，千里佳人应共看。"]},{"t":"题明初所藏暮云楼阁图","f":"七言绝句","c":["倚空寒立翠孱颜，楼在重云缥缈间。","松下罢琴人未去，夕阳应待鹤飞还。"]},{"t":"题明初所藏青山白云图","f":"七言绝句","c":["不成苍狗不成衣，添出峰峦一段奇。","云去云来山自若，笑它前日作霖时。"]},{"t":"咏徐氏竹溪之景八首 其一 溪上楼","f":"七言绝句","c":["一曲清波不受尘，倚阑长日玩奫沦。","风烟莫道翁收尽，撞透烟楼更有人。"]},{"t":"咏徐氏竹溪之景八首 其二 竹间楼","f":"七言绝句","c":["高居已是脱卑凡，况在萧森冷翠间。","欲识此君清绝处，尽遮尘俗不遮山。"]},{"t":"咏徐氏竹溪之景八首 其三 扁舟亭","f":"七言绝句","c":["陆居无屋舟无水，得似先生屋作舟。","人海茫茫我何有，且教满载一天秋。"]},{"t":"咏徐氏竹溪之景八首 其四 蓝田别墅","f":"七言绝句","c":["辋川丘壑蔓寒藤，境异心同有此名。","见说主人惟种德，不须石子玉还生。"]},{"t":"咏徐氏竹溪之景八首 其五 桂墩","f":"七言绝句","c":["翁家多桂郁成堆，几度秋风几世栽。","好是麟儿成宅相，蟾宫又折一枝回。"]},{"t":"咏徐氏竹溪之景八首 其六 钓台","f":"七言绝句","c":["石岩云矗俯深溪，下有清风动一丝。","我亦忘鱼聊复尔，可怜温水误昌黎。"]},{"t":"咏徐氏竹溪之景八首 其七 石坞潭","f":"七言绝句","c":["郿坞金多竟不存，清坚输与老云根。","潭中鳣鲔知多少，已有飞腾过禹门。"]},{"t":"咏徐氏竹溪之景八首 其八 军山","f":"七言绝句","c":["昔年屯聚亦偷生，今日柴扉夜不扃。","却羡此山能领会，时危时泰一般青。"]},{"t":"题子昂竹石","f":"七言绝句","c":["坡仙戏墨是信手，松雪晚年深得之。","两竿瘦竹一片石，中有古今无尽诗。"]},{"t":"题班彦功山水扇图","f":"七言绝句","c":["钱塘江上又秋风，老友沦亡梦不通。","胜槩肯教同羽化，山河写在月轮中。"]},{"t":"作乐导水 其一","f":"七言绝句","c":["洹溪混混源头活，分得枝流入小塘。","怪底凝云吹不散，管弦声满水中央。"]},{"t":"作乐导水 其二 槜榼落成","f":"七言绝句","c":["一斝才空一曲随，胼胝今日顿忘疲。","年来怀抱须陶写，敢笑长安众富儿。"]},{"t":"作乐导水 其三 柳下听莺","f":"七言绝句","c":["万条金缕袅长身，勾引迁乔语意新。","休向建章誇百转，陶家门径有馀音。"]},{"t":"作乐导水 其四 舟中对鹭","f":"七言绝句","c":["禅定联拳敛素裳，岂知船上载红妆。","主人有约休相负，多少鱼儿要汝忘。"]},{"t":"作乐导水 其五 荷觞酌酒","f":"七言绝句","c":["野人饮具谢玻璃，自有天然软玉卮。","荡漾翠涛擎不定，有人谋笑任淋漓。"]},{"t":"作乐导水 其六 蕉叶题诗","f":"七言绝句","c":["骚乡缣楮寓芭蕉，翠瑩尤宜运紫毫。","风致于诗真有助，卯君才调况清高。"]},{"t":"作乐导水 其七 荷净纳凉","f":"七言绝句","c":["柳阴多处著方床，万柄无尘各有香。","危坐悠然受清供，风声摵摵更秋凉。"]},{"t":"作乐导水 其八 开窗看雨","f":"七言绝句","c":["一时清响闹新荷，其奈龙公不肯多。","窗外风光吾不校，四郊禾黍定如何。"]},{"t":"作乐导水 其九 松阴独钓","f":"七言绝句","c":["半世京华困鼎茵，高风时复梦玄真。","可怜缘木求鱼者，今日君其问水滨。"]},{"t":"作乐导水 其十 与客泛舟","f":"七言绝句","c":["欸乃声中动画桡，不须舟子更相招。","而今赤壁荒寒里，试问何人有洞箫。"]},{"t":"作乐导水 其十一 日夕观山","f":"七言绝句","c":["林虑千仞翠岩岩，罨画工夫在暮岚。","徙倚崇台观未足，红轮西北月东南。"]},{"t":"作乐导水 其十二 西堤晚眺","f":"七言绝句","c":["小亭何用赤阑桥，细柳新荷绿四遭。","落日胡床更东望，碧天如水月轮高。"]},{"t":"作乐导水 其十三 雨中移竹","f":"七言绝句","c":["山人聚景作池台，移得龙孙带雨栽。","顷刻云开晴日上，便教阴过酒樽来。"]},{"t":"作乐导水 其十四 月下观梅","f":"七言绝句","c":["空明云水碧摇沙，疏影尤宜竹外斜。","为我殷勤谢伧父，莫疑繁李玉川家。"]},{"t":"作乐导水 其十五 倚槛观鱼","f":"七言绝句","c":["鱼乐江湖自不知，非鱼非我敢相欺。","卮言我不如庄惠，终日观鱼只有诗。"]},{"t":"作乐导水 其十六 绕堤种菊","f":"七言绝句","c":["纷纷红紫厌相看，老境才将蔗倒餐。","不向四堤皆种菊，风霜谁与共高寒。"]},{"t":"作乐导水 其十七 竹间开径","f":"七言绝句","c":["翠寒深处覆苍苔，香雾霏霏晚自开。","从此一筇双不借，寻诗迎客几徘徊。"]},{"t":"作乐导水 其十八 水口听琴","f":"七言绝句","c":["幽栖长物一张琴，时对清流自写心。","老子兴阑童子去，月明悬溜有馀音。"]},{"t":"作乐导水 其十九 独坐投壶","f":"七言绝句","c":["绿阴清昼矢鸣壶，庆马何烦用酒娱。","有主无宾聊一笑，却呼僮仆煮皋卢。"]},{"t":"作乐导水 其二十 登台纵目","f":"七言绝句","c":["老眼常疑万象低，凭高远景更萋迷。","只从此地观吾圃，便觉江湖是小溪。"]},{"t":"作乐导水 其二十一 调白莲","f":"七言绝句","c":["仙姿皎洁映圆台，真见凌波恣意开。","却是圭塘宜产汝，朝阳东照玉成堆。"]},{"t":"作乐导水 其二十二 调水芙蓉不花","f":"七言绝句","c":["南土风宜陆地莲，移根培植不能妍。","世间久绝司花手，却道殷韩是偶然。"]},{"t":"作乐导水 其二十三 调湖石","f":"七言绝句","c":["一卷千古碧崔巍，阅尽人间紫与绯。","老子未能兄事汝，醉来聊用挂絺衣。"]},{"t":"作乐导水 其二十四 听筝","f":"七言绝句","c":["冰弦轰列倚歌轻，弦外无声却有声。","我自忘情聊过耳，几人闻此发狂醒。"]},{"t":"酒间得口号二十八字","f":"七言绝句","c":["卯君为我凿圭塘，荆棘化为云水乡。","昨夜荷香新雨过，一年劳费尽销忘。"]},{"t":"大雨两昼夜僮屋尽仆惟轩前新竹绰有生意得二十八字以为口号","f":"七言绝句","c":["一夜银河泻欲乾，桑田几似海漫漫。","岸颓墙仆吾无憾，栽活苍筤数百竿。"]},{"t":"雨后观竹乃有堙垫摧折者数丛因用前韵","f":"七言绝句","c":["忆昨移栽怕雨乾，岂期平地水瀰漫。","此君于我真无负，摧折犹堪作钓竿。"]},{"t":"盆菊联句","f":"曲","c":["霜卉日已腓，寒轧层空澄。","大明丽若木，忽自东海升。","照我衡茅下，南金烂棱层。","密叶肥晚翠，疏根瘦秋鹰。","眷兹贞淑质，夙著隐逸称。","佳名岂易得，高风邈难仍。","心将东篱兴，迹遽华筵登。","美人遂幽讨，晚岁欣得朋。","谁令赪与紫，亦复相依冯。","黄裳本元吉，间色讵能胜。","颀然挺寻丈，欹倾待维绳。","植以葛陂杖，资以剡溪藤。","通谱品逾百，口说为尔滕。","宗既别大小，祖亦殊高曾。","浓如胭脂沁，润如酥膏凝。","鲜如剪朝霞，清如裁春冰。","肉色映蒙絺，体素动砑绫。","百叠甃碎琼，千重蹙文缯。","莺羽乍出鷇，鱼鳞骈有棱。","亭亭矗巨杯，灼灼开华灯。","长身不免弱，擎重嗟未能。","摘剔留数花，花损气益增。","出奇世岂眩，夺巧天应憎。","人力固云胜，物性柰失恒。","平生愧学诗，多识犹儚儚。","不如坐对之，政似罗豆?。","真趣渐渐得，香气浮浮蒸。","微吟慰晚节，大滕哦松丞。","有花思陶潜，无酒思王弘。","南阳饮潭水，寿者如冈陵。","所以遁世翁，有乐在曲肱。","傲睨风露表，春花我方惩。","况为养性药，服之可鶱腾。","当年与花别，待漏常鸡兴。","縻爵梦三径，归田薙荒艿。","三径幸犹存，清兴聊复乘。","庶几韦表微，千载骥附蝇。","客来涉吾圃，老圃唤不应。","灌溉瓶屡罄，咏歌笔已蹭。","身虽老瓦托，气欲南山凌。","野人富胜事，行有梅继承。","此盟未歃血，此语已服膺。","又恐远莫移，健步劳屩縢。","孤根岂幡然，遂用玉帛徵。","彼蕙树百亩，妄以多自矜。","芳枝愧真坚，恐负骚人譝。","真赏各有适，蜂蝶徒䎕䎕。","诗坛战戈甲，齐晋压杞鄫。","尚怜秋如海，?之以斗升。","从公丐一勺，临渊剧兢兢。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其二","f":"五言古诗","c":["寝迹非绝世，雅志便林丘。","青山足一至，胜处靡不游。","意适辄忘返，兹焉夏已秋。","遥遥目力穷，青青尽田畴。","迷复幸不远，归欤无异谋。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其三","f":"五言古诗","c":["脱身豪侠窟，里氓缔新交。","爱其心无阱，不较醉语譊。","生儿更有教，治地尽肥硗。","禾黍已在眼，瓜蔬早登庖。","愧子良已多，况敢希由巢。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其四","f":"五言古诗","c":["浮生苦无悰，道近人自远。","重外乐徇身，遗世几赫咺。","老农初不知，遑遑岁年晚。","清晨负耒出，日夕行歌返。","悠悠千载心，他人莫予忖。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其五","f":"五言古诗","c":["落日照我影，颀然溪水中。","凉飙动絺衣，势欲凌虚空。","顾之一大笑，与尔将无同。","昔也尔何达，兹焉尔何穷。","莫道山林陋，乃有黄虞风。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其六","f":"五言古诗","c":["昔人植松柏，映蔚弥崇冈。","不为朝夕利，千载当自长。","植槿非不荣，我圃因之荒。","白发走畏途，途修马非良。","桑榆赖未晚，此乐且无央。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其七","f":"五言古诗","c":["静念少日事，躁中剧揠苗。","欲令千载淳，反之在一朝。","斥鴳不自量，上欲抟扶摇。","世态任盲俗，林讥愧清谣。","傲骨日已长，及辰事逍遥。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其八","f":"五言古诗","c":["渊明昔归休，开岁才五十。","我虽年近似，我道惭什百。","兼金与尺璧，敢取侪瓦砾。","缅焉动真想，迅往孰诱掖。","庶几归田园，千载可同迹。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其九","f":"五言古诗","c":["我闻昔桃源，民风近无怀。","兹山亦深窈，中有读书斋。","但绝车马迹，不惜云烟埋。","旁围靡靡山，上荫高高槐。","聊以永今朝，得酒从无膎。"]},{"t":"神山避暑晚行田间用陶渊明平畴交远风良苗亦怀新为韵 其十","f":"五言古诗","c":["我发日以变，山色日以新。","举杯试问山，古今阅几人。","我非山主人，聊为山之宾。","杖可入幽险，诗能写清淳。","但恐我他适，山乎尔谁邻。"]},{"t":"谢吴閒閒大宗师寄鹤氅衣","f":"五言古诗","c":["逆骈欲遗世，异服事缪悠。","恭也差可观，未是真仙俦。","因服究其衷，有怀小竹楼。","一时示萧散，千载瞻风流。","鄙人冒朱紫，因循成白头。","衣锦不尚絅，褫带宜承羞。","归来作褐父，敝缊寒无忧。","老仙独不弃，谓可同真游。","解衣远衣我，意重千金裘。","高义固多感，浊骨难昆丘。","披之焚香坐，世虑忘嚣湫。","神仙未能学，愿学王黄州。"]},{"t":"陈芝田写余真对之小酌戏成四韵","f":"五言律诗","c":["今日我与汝，相看各华颠。","亟呼尊酒至，我饮汝茫然。","他年我长往，酒但酬汝前。","悟此一大笑，沽酒休论钱。"]},{"t":"和林春野见寄韵 其一","f":"五言古诗","c":["山中真可乐，经旬无客来。","群材足楩楠，小臣甘草莱。","君看倦飞鸟，投林不徐徊。","咄尔迷途人，伥伥自纡回。","海鸥久已狎，鸬鹚复何猜。","秋风看木落，春风看花开。","既种子猷竹，亦有逋仙梅。","先生可休矣，大夫亦贤哉。","高步云汉阔，蹒跚距能陪。","尚可学采药，谈笑到天台。"]},{"t":"和林春野见寄韵 其二","f":"五言古诗","c":["士生如大木，皆欲架明堂。","宁知施用处，用圆吾乃方。","归来何所事，琢句敷肾肠。","既为烟霞痼，复作花月荒。","一壑今已专，万景身可当。","山空白石烂，云尽青天长。","故人远相慰，瑰辞联夜光。","一展发晔晔，再诵铿琅琅。","贞松无冶容，老桂多古香。","三复如见君，岁晚谁能忘。"]},{"t":"宿临湘赠诚之监县","f":"五言古诗","c":["北风橹声乾，晚泊断矶下。","云岫浮修蛾，霜生入平野。","鸿雁无处寻，落日不可画。","重冈护岩邑，百里寄民社。","藉甚贤大夫，居然鲁恭化。","丰年足粳稻，沃壤满桑柘。","我如无心云，底事劳候迓。","烂醉得诗归，江山非传舍。"]},{"t":"李伯徵中丞奉东宫命作椎结请纪其故以百字颂而祝之","f":"五言古诗","c":["总角习义方，结发事明主。","栉纵豸且貂，勤劳几寒暑。","青皇一顾中，遂与国人伍。","区别垂鬒云，岐分戢鸦羽。","昔我秋谷公，爬搔净寰宇。","象贤实无愧，冠服俨前矩。","愿言寿而康，三握勿为苦。","他年麟阁上，雪鬓照簪组。","何用拭肝石，道贵随所处。","老我任飞蓬，歌诗美绳武。"]},{"t":"次韵可行记圭塘草木 其一","f":"五言律诗","c":["吾家青牛君，伯仲龙矫矫。","不似丁令威，暂来立华表。","鬼神护斧斤，风霜几昏晓。","摩挲左纽文，曾见陆为沼。"]},{"t":"次韵可行记圭塘草木 其二","f":"五言律诗","c":["徂徕以多贱，吾圃斯拔萃。","远从他山移，清与幽境会。","乐天才四十，栽尔已兴慨。","吾年六十三，方期翠成盖。"]},{"t":"次韵可行记圭塘草木 其三","f":"五言律诗","c":["长公有名言，不可居无竹。","仆仆斸苍苔，森森植寒玉。","声来书幌清，阴入酒杯绿。","何须更晚食，此君足当肉。"]},{"t":"次韵可行记圭塘草木 其四","f":"五言律诗","c":["苍官昔多事，乃与群鸟邻。","何如在圭塘，亦胜居神囷。","老根已作石，霜皮不成鳞。","不用叹不遇，参军能写真。"]},{"t":"次韵可行记圭塘草木 其五","f":"五言律诗","c":["朝来花斩新，暮雨坠红湿。","藤萝助奇观，罗帔层层碧。","昌黎性苦隘，政尔要蒙羃。","一笑问秋乎，还能诲人弈。"]},{"t":"次韵可行记圭塘草木 其六","f":"五言律诗","c":["披披青罗扇，敷阴圭塘阿。","夏窗云影薄，秋枕雨声多。","翰墨聊复尔，风霜其若何。","休教近湖石，掩映美人歌。"]},{"t":"次韵可行记圭塘草木 其七","f":"五言律诗","c":["人生念慈亲，堂阶多树萱。","忽随灵椿化，冥漠俱高骞。","此忧讵可忘，肝摧不能言。","对花差自慰，白头还抱孙。"]},{"t":"次韵可行记圭塘草木 其八","f":"五言律诗","c":["昔人避秦乱，川原多种桃。","我幸遇明世，栽培胡自劳。","看花食其实，为圃岂不遭。","疏懒强鞭策，犹胜宅不毛。"]},{"t":"寄归彦温","f":"五言古诗","c":["林虑吾郡山，弃之来浚都。","子实浚都人，乃得居林虑。","出疆必载质，浮海或乘桴。","圣贤义有在，并介遂殊途。","静言复自咎，九徵有不渝。","袁闳筑土室，苑粲安一车。","六月拥裘卧，异世真同符。","何当云壑里，添我一茅庐。"]},{"t":"应制天马歌","f":"曲","c":["臣闻圣元水德正色在朔方，物产雄伟马最良。","川原饮龁几万万，不以数计以谷量。","承平云布十二闲，华山百草春风香。","又闻有骏在西极，权奇俶傥钟乾刚。","茂陵千金不能致，直以兵戈劳广利。","当时纪述虽有歌，侈心一启何由制。","吾皇慎德迈前古，不宝远物物自至。","佛郎国在月窟西，八尺真龙入维絷。","七逾大海四阅年，滦京今日才朝天。","不烦剪拂光夺目，正色呈瑞符吾玄。","凤鬐龙臆渴乌首，四蹄玉后䃜其前。","九重喜见远人格，一时便敕良工传。","玉鞭锦鞯黄金勒，瞬息殊恩备华饰。","天成异质难自藏，志在君知不在物。","方今天下有道时，绝尘讵敢称其力。","臣才罢驽亦自知，共服安舆无覂轶。"]},{"t":"题友人所藏明妃图","f":"七言古诗","c":["臂香骨沁守宫虐，金锁重门怨银钥。","深宫有眼不识春，昼长时听云间乐。","平生所见惟监宫，今朝岂期见画工。","君王知画不知妾，薄命已分如秋蓬。","黄沙漫漫天无穷，惊飙吹老红芙蓉。","穹庐明日又何处，此生遂负南归鸿。","和亲纳侮号上策，建议诒谋娄敬责。","妾身虽苦免主忧，犹胜专宠亡人国。","关山寥落梦亦迷，嫁鸡正尔随鸡飞。","人间生女莫望贵，只可近作田家妻。","琵琶声断霜天月，青冢至今青不歇。","后来却有蔡文姬，千古胡笳辱哀拍。"]},{"t":"行建德县民有诉作桥罹害者作徒杠行","f":"七言古诗","c":["霜馀溪湍息奔斗，农隙维时梁可构。","往来恐有病涉人，官著恒规谁敢后。","邑胥承帖来乡里，乡民见胥如见鬼。","督材斩木到丘垄，致期视成殴妇子。","人未安行力已疲，冬无旨蓄鸡先死。","田家鸡尽诚可哀，邑宰旦夕行桥来。","吁嗟此役本为利，谁知为害翻百倍。","老癃伛偻诉且泣，莫遣吏监民自力。","治贪问瘼乃吾事，去甚痛惩尤所急。","老癃又言官试听，今日所知百无一。","我闻此语愤填膺，不可胜诛空太息。","安得落落寰区间，尽是龚黄二千石。"]},{"t":"临江见大船宏丽异甚赋贾客乐","f":"七言古诗","c":["鼓声震荡冯夷宫，帆腹吞饱江天风。","长年望云坐长啸，稳驾万斛凌虚空。","主人扬州卖盐叟，重楼丹青照窗牖。","斗帐香凝画阁深，红日满江犹病酒。","钱塘女儿静且姝，臂金盈尺衣六铢。","凭阑饭饱观戏鱼，清波照影红芙蕖。","江城到处时弥楫，遍买甘鲜穷所悦。","千里携家任去留，一生为客无离别。","敦农抑商昧远计，遂使素封轻得意。","握筹狡狯俯承命，危坐咄嗟收厚利。","田庐彫敝君知否，终岁勤劳莫糊口。","夏税未了秋税来，三十六策惟有走。"]},{"t":"喜逢口","f":"七言古诗","c":["儿寒解衣重抚摩，儿饥推食孰忍诃。","长成与国远负戈，一去不返当如何。","去时云戍东北鄙，直出榆关度辽水。","白头郎罢与影俱，岂惮山川千万里。","天教此地适相逢，父曰从天坠吾子。","笑疲乐极俱殒身，谁谓情钟遽如此。","官家开边方未已，同生又别宁同死。","山云漠漠风飕飕，山头双冢知几秋。","当时不忍一朝喜，今日翻飞千载愁。","犹胜贞女化为石，终古孤身双不得。","清江寒影日悠悠，行人一去无消息。"]},{"t":"赤壁","f":"七言古诗","c":["孽瞒祸水剧赵女，汉火馀光能几许。","蜀方传薪嘘未然，吴偶束缊成一炬。","万艘枯苇沃以膏，空江如韛长风鼓。","九渊鼎沸羹鱼龙，连营炽炭膰貔虎。","雄图南纪成画饼，匹马华容作穷鼠。","坡翁乘兴赋赤壁，烂漫天机涌毫楮。","偶从雪里写芭蕉，又似骊黄不毛举。","考图求故此其地，疾恶千年若躬睹。","江山萧条岁华晚，兴废人间几今古。","买鱼沽酒吊阿瞒，醉和渔歌短蓑舞。"]},{"t":"雷篷歌赠廖楚材山长","f":"七言古诗","c":["人间尘土何地无，道人自爱居江湖。","江湖佳处写不尽，且复想像陈其觕。","有舟如叶君勿笑，气象乃欲吞堪舆。","四时风景皆可乐，岁晚独与天游俱。","青山昨夜忽遁去，万象一色涵冰壶。","眼界疑堕清虚府，心境直造鸿荒初。","道人箕踞受奇供，但讶光怪生籧篨。","霜筠露箨政不俗，更欲缘饰为琼琚。","湘江清碧俯见底，岳麓倒影寒萦纡。","兴来不省有物我，短蓑独速歌吴歈。","可怜翠被秦复陶，但鼓忧患来攻驱。","莫言雪尽篷遂废，敲雨承月仍相娱。"]},{"t":"哀弃儿","f":"楚辞体","c":["雪霜载途风裂肌，有儿鹑结行且啼。","问儿何事乃尔悲，父母弃之前欲追。","木皮食尽岁又饥，夫妇行乞甘流离。","负儿远道力已疲，势难俱生灼可推。","与其疐尾莫我随，不如忍割从所之。","今夕旷野儿安归，明朝道殣非儿谁。","父兮母兮岂不慈，天伦遽绝天实为。","卜年执政虽咸腓，发廪有议常坚持。","昔闻而知今见之，仓皇援手无所施。","儿行不顾寒日西，哭声已远犹依稀。"]},{"t":"偶阅可行书见其印章曰洹溪钓者戏为野语","f":"七言古诗","c":["道士只合山中居，钓者只合溪中渔。","不山不溪朝市趋，人轻尔厌重尔诬。","彼道士者尤迂愚，妄欲跻世为唐虞。","平生动为鬼揶揄，况负且乘招而呼。","山耶溪耶盍归欤，山有美茹溪有鱼。"]},{"t":"李惟中学士自西台侍御召入以未央宫瓦砚为贶作此谢之","f":"七言古诗","c":["汉家作宫法紫微，金铺玉户明华榱。","甄官陶瓦极能事，铅丹细捣咸阳泥。","一朝神雀去不返，秋风禾黍惊离离。","谷陵且变此宜尽，一二时出农夫犁。","人间购求作珍玩，洗刷篆籀分毫釐。","西台执法好事者，砻磨为砚尤瑰奇。","体呈全璧径尺许，沼开新月才一眉。","坚如铁石润如玉，墨声瑟瑟松风吹。","惠然匣送感高义，但惜所与非所宜。","公才真是谪仙裔，善事利器方相资。","嗟予芜学忝词馆，虽有此器无能为。","世传铜雀亦佳品，搜刔黄壤今无遗。","高皇垂统四百载，老瞒何物敢等夷。","爱人屋上乌亦好，况兹适用逾端溪。","楮生毛颖贺得友，坐令几案增光辉。","代言挥制固多愧，玉堂风月犹能诗。"]},{"t":"中书久病得请将归吴閒閒大宗师亦有疾以其象为赠云代彼陪行焚香对之作此以谢","f":"曲","c":["宵人本是山泽臞，涉世政坐饥寒驱。","五年黄阁事何补，种作老病丛孱躯。","滦京归来十浃日，药裹不可离须臾。","平生结客半寰宇，未免操瑟从齐竽。","可人底事期不来，承庆堂深谁敢呼。","迩来亦复诗作祟，清减益见风标孤。","杜门却扫难折简，岂意惠然来画图。","相看一笑但臆对，妙契未许卮言?。","清冰寒玉照林表，和气春风生座隅。","斋居顿觉俗氛远，高致已逼沈疴苏。","我方归思剧迅矢，公自有分居方壶。","过从此去计必少，梦中道路多萦纡。","便当卷奉江湖去，愿得始终如蟨驉。"]},{"t":"小楼对閒閒宗师象因次旧韵寄之","f":"曲","c":["鼎食不解肥我臞，多病亦为山林驱。","巾车孤舟任所适，何往不可容微躯。","莫言五十未为老，纵有七十来须臾。","今年两耳得差胜，饱听万籁吹笙竽。","閒人多事迫诗债，野老败兴时招呼。","小楼今日好风色，目断天末冥鸿孤。","一时幽兴岂容负，况对蓬岛神仙图。","篆烟凝坐共心赏，尽醉更把空尊?。","怀人未免有芥蒂，处世已赏无廉隅。","分江小鼎煮粟粒，诛茅别墅营屠苏。","远山但藉一枝杖，中流谁辨千金壶。","菊篱秋香晚未减，松窗月色寒相纡。","我行不武分敛迹，安得甘草资蛩驉。"]},{"t":"沙湖道中","f":"五言律诗","c":["城居如坐井，出郭始知春。","草色才翻烧，禽声便可人。","远山来逦迤，羸马去逡巡。","唤醒三年梦，东华足软尘。"]},{"t":"田家对雪","f":"五言律诗","c":["野老能留客，柴门便反关。","落梅点衣上，飞雪堕杯间。","地僻偏宜竹，窗幽更对山。","自怜真野逸，瓶罄不知还。"]},{"t":"夜至鲁港","f":"五言律诗","c":["桴鼓远铜笼，前驱列炬红。","星芒寒拂地，江影静浮空。","听语渔村近，连航水驿通。","不才惭传食，鲑菜足为供。"]},{"t":"夜行润陂","f":"五言律诗","c":["荡荡唐虞世，区区虱蚁臣。","露餐乌攫肉，夜渡马知津。","危栈依山尽，微行到水频。","风霜尽蒙犯，庶用答涓尘。"]},{"t":"神山雨","f":"五言律诗","c":["山中日日雨，松竹早知秋。","清响自深夜，逸人无远愁。","窗虚闻叶落，林暗见萤流。","对景因怀杜，江村事事幽。"]},{"t":"登后山观湖涨时阴雨忽霁","f":"五言律诗","c":["阴磴盘盘上，枯藤得得来。","长杨半腰水，老桂一身苔。","秋气蛩先觉，风声鹤欲回。","山云自行雨，休为老夫开。"]},{"t":"晚过韶州","f":"五言律诗","c":["世去重华远，名偕二石存。","溪寒清见底，榕老乱垂根。","野色偏宜晚，民居仅似村。","曲江人已矣，楚些拟招魂。"]},{"t":"横浦登舟","f":"五言律诗","c":["南征殊不恶，乐事总相关。","马上行思句，舟中卧看山。","尽收烟景去，满载月明还。","何往不自得，浩歌天地间。"]},{"t":"上京十咏 其一 马酒","f":"五言律诗","c":["味似融甘露，香疑酿醴泉。","新醅撞重白，绝品挹清玄。","骥子饥无乳，将军醉卧毡。","祠官闻汉史，鲸吸有今年。"]},{"t":"上京十咏 其二 秋羊","f":"五言律诗","c":["塞上寒风起，庖人急尚供。","戎盐舂玉碎，肥羜压花重。","肉净燕支透，膏凝琥珀浓。","年年神御殿，颁馂每沾侬。"]},{"t":"上京十咏 其三 黄羊","f":"五言律诗","c":["草美秋先腯，沙平夜不藏。","解绦文豹健，脔炙宰夫忙。","有肉须供世，无魂亦似獐。","少年非好杀，假尔试穿杨。"]},{"t":"上京十咏 其四 黄鼠","f":"五言律诗","c":["北产推珍味，南来怯陋容。","瓠肥宜不武，人拱若为恭。","发掘怜禽狝，招徕或水攻。","君毋急盘馔，幸自不穿墉。"]},{"t":"上京十咏 其五 籸面","f":"五言律诗","c":["坡远花全白，霜轻实便黄。","杵头麸退墨，硙齿雪流香。","玉叶翻盘薄，银丝出漏长。","元宵贮膏火，蒸墨笑南乡。"]},{"t":"上京十咏 其六 芦菔","f":"五言律诗","c":["性质宜沙地，栽培属夏畦。","熟登甘似芋，生荐脆如梨。","老病消凝滞，奇功直品题。","故园长尺许，青叶更堪齑。"]},{"t":"上京十咏 其七 白菜","f":"五言律诗","c":["土羔新且嫩，筐筥荐纷披。","可作青菁饭，仍携玉版师。","清风牙颊响，真味士夫知。","南土称秋末，投簪要及时。"]},{"t":"上京十咏 其八 沙菌","f":"五言律诗","c":["牛羊膏润足，物产借英华。","帐脚骈遮地，钉头怒戴沙。","斋厨供玉食，毳索出毡车。","莫作垂涎想，家园有莫邪。"]},{"t":"上京十咏 其九 地椒","f":"五言律诗","c":["冻雨催花紫，轻风散野香。","刺沙尖叶细，敷地乱条长。","楚客收成裹，奚童撷满筐。","行厨供草具，调鼎尔非良。"]},{"t":"上京十咏 其十 韭花","f":"五言律诗","c":["西风吹野韭，花发满沙陀。","气校荤蔬媚，功于肉食多。","浓香跨姜桂，馀味及瓜茄。","我欲收其实，归山种涧阿。"]},{"t":"寻梅","f":"五言律诗","c":["何以慰吾衰，梅花秀发时。","晚香传远树，春雪避南枝。","林静来差早，溪深行独迟。","与君谋一醉，及此未离披。"]},{"t":"水木清华亭宴集十四韵并序","f":"五言古诗","c":["世禄推门阀，天墀几拜嘉。","高情忘势利，大隐谢纷哗。","朝市尘无染，蓬瀛路岂赊。","眷言营别墅，初不远东华。","画舸堂前过，青帘柳外斜。","晴红迷菡萏，寒翠接蒹葭。","挥麈风生座，扶筇雨压沙。","萍开轻泛鸭，荷侧重擎蛙。","只讶神仙府，谁知宰相家。","宾朋玄圃玉，文采赤城霞。","丽曲凝云表，仙妆炫水涯。","添栽三径竹，递赏四时花。","心事尊中物，人生海上槎。","相逢须尽兴，明日各趋衙。"]},{"t":"送马明初教授南归二十韵并序","f":"五言古诗","c":["吾子昔倾盖，琅瓈古渡头。","袖文惊蜀锦，怀宝重天球。","心既同金断，胶因向漆投。","有邀须共往，无倡不为酬。","南岳朝联辔，湘江暮舣舟。","屐穷峰顶寺，诗满水边楼。","访古由来喜，寻芳到处留。","遂移衡浦隐，便作武昌游。","坐席何曾暖，招旌遽见求。","高情安旅次，遐躅又神州。","道路多尝险，山川只荐愁。","扫云髡兔颖，鏖雪敝貂裘。","善诱儿何幸，深藏价未收。","忽看鸿鹄举，甘效蟨蛩休。","洹水寒偏瑩，林虑晚更幽。","谁知三仕已，相累十春秋。","公道先扬善，真才自拔尤。","恩袍明翡翠，教铎振貔貅。","行役仍清淡，言归邈阻修。","临岐惟一语，音信莫悠悠。"]},{"t":"寿李秋谷平章","f":"七言律诗","c":["黄钟嘘㬉挽春留，绿蚁浮香带月篘。","宰相得閒才是贵，人生有子更何求。","家传文字五千卷，身在神仙十二楼。","记取年年好风景，雪松霜桧岂容秋。"]},{"t":"送黄文复归长沙","f":"七言律诗","c":["半生湖海梦依稀，但诵湘南远寄诗。","先友凋残公独健，故园荒尽我方归。","百年未满常忧畏，千里相逢又别离。","他日瓈江松下路，西州难似此沾衣。"]},{"t":"横山有高竹楼别业留信宿始归","f":"七言律诗","c":["酒香牲腯主人归，正是猿惊鹤怨时。","梅影小池春入画，竹声虚阁夜催诗。","世间真乐无多事，身外浮名只费辞。","他日结茅容我隐，一章先当买山赀。"]},{"t":"九日陪阖台诸公登石头城","f":"曲","c":["一江环抱四山围，酬节追欢剩费诗。","雁影不移云尽处，秋光都在雨晴时。","当年玉树人何在，明日黄花蝶岂知。","便驻高轩?醉倒，绝胜无酒绕东篱。"]},{"t":"题昌平刘建议祠","f":"七言律诗","c":["一卷春秋两鬓皤，丹诚贯日口悬河。","策能匡世时不用，天实厌唐人奈何。","自古大材多薄命，而今我辈亦登科。","可怜熏腐俱尘土，得似高名永不磨。"]},{"t":"游昌平憩县学归过朱都督碑","f":"七言律诗","c":["木叶才霜水不波，偷閒今日遂婆娑。","清秋林壑斜阳好，丰岁郊原乐事多。","秦塞已隳仍郡县，武城虽小有弦歌。","却怜一片朱家石，千古泾原臭不磨。"]},{"t":"神山即事","f":"七言律诗","c":["京尘汨没已华颠，恰是山居第一年。","松月照窗诗入圣，竹风吹榻梦游仙。","随人久作悠悠者，处世方知绰绰然。","尚愧未能忘口腹，时劳昆季致肥鲜。"]},{"t":"和谢敬德学士见寄韵 其一","f":"七言律诗","c":["平生疏懒是天姿，今岁春来起亦迟。","好酒或如陶靖节，杜门深愧郑当时。","向来事业惟供笑，如此风光忍废诗。","馆阁真才试枚举，鹄山陪预恐难期。"]},{"t":"和谢敬德学士见寄韵 其二","f":"七言律诗","c":["淡霭轻风弄野姿，江天寥廓鸟飞迟。","从知宇宙多閒地，谁信襟怀胜旧时。","夜雨不惊逋客梦，暮云犹入故人诗。","山中亦有阳春曲，拂拭朱弦待子期。"]},{"t":"登岳阳楼","f":"七言律诗","c":["半空轮奂壮巴丘，消得骚人一系舟。","云气远携湘雨至，湖光寒入蜀江流。","山川信美非吾土，天地无穷有此楼。","三十四年如梦过，可怜华发赋重游。"]},{"t":"黄陵庙","f":"七言律诗","c":["黄陵庙下草萋萋，水远山长听竹枝。","末路不求同死处，重华宁有再来时。","霜筠苦泪留千古，野树愁云接九疑。","珍重韩公修废坠，却怜侥福类神私。"]},{"t":"过湘潭","f":"七言律诗","c":["江边杨柳翠萦回，柳外人家罨画开。","一夜东风花落尽，千年华表鹤归来。","暮云山出远浮黛，春雨水添浓泼醅。","莫舣扁舟访陈迹，白头怀抱易生哀。"]},{"t":"祝融峰与廷镇觞咏有怀欧阳原功盖尝约同游而予不能待其归也","f":"七言律诗","c":["载酒穷跻最上峰，啸歌声撼海涛风。","得陪五马二千石，独少三生六一翁。","为问北门红日下，何如南岳白云中。","寄诗几欲申前约，无奈人生似燕鸿。"]},{"t":"时雨忽降簿书甚稀独坐王可矩右司有诗次其韵 其一","f":"七言律诗","c":["翠樾云深百鸟鸣，彤闱如水嫩凉生。","雨声自与诗有约，天巧岂容人强名。","万里秋风黄鹄梦，五湖春水白鸥盟。","年来不用愁华发，尚有观山老眼明。"]},{"t":"时雨忽降簿书甚稀独坐王可矩右司有诗次其韵 其二","f":"七言律诗","c":["西厅东阁总诗鸣，天籁相关触处生。","京国故人多老病，洛阳才子独声名。","风云幸际文昌运，松柏休忘岁晚盟。","他日江湖携手去，尽渠蚊睫有焦明。"]},{"t":"题武卫段指挥书林","f":"七言律诗","c":["相府深沈书若林，牙签插架列森森。","千枝万叶本根在，二帝三王雨露深。","椔翳斯文功利学，栋梁来世圣贤心。","经残百氏纷纭出，慎勿轻栖恶木阴。"]},{"t":"閒居杂诗 其一","f":"七言律诗","c":["鬓发苍浪齿动摇，自知宜退待谁招。","茶馀引鹤消春昼，酒醒闻鸡记早朝。","肥截玉肪羹缩项，香翻云子饭长腰。","尚嫌门有徵诗客，时与山人破寂寥。"]},{"t":"閒居杂诗 其二","f":"七言律诗","c":["半山云树接修篁，镇日无尘到草堂。","瓮牖风来书叶乱，胆瓶花落砚池香。","壶觞自酌教微醉，松菊犹存及未荒。","护果灌园常不暇，谁知閒里更多忙。"]},{"t":"閒居杂诗 其三","f":"七言律诗","c":["鹄山东北接郊墟，郭影岚光画不如。","九十日春朝暮雨，两三间屋古今书。","庭花红碍经行处，园竹青回剪伐馀。","满地苍苔愁踏破，年来深喜故人疏。"]},{"t":"閒居杂诗 其四","f":"七言律诗","c":["窃禄多惭号具臣，归田何幸作閒人。","登山临水今非客，病酒愁花又过春。","梦断紫霄黄阁远，眼明青镜白头新。","芥薹竹笋来相续，不道茅柴味更真。"]},{"t":"和傅汝砺寄来韵 其一","f":"七言律诗","c":["江水舟航日夜东，故人音问得常通。","君才能挽千钧重，我老惟怀一亩宫。","自古山林容小隐，只今台省有诸公。","欲知别后诗成处，都在花香竹影中。"]},{"t":"和傅汝砺寄来韵 其二","f":"七言律诗","c":["春红园圃眩西东，花下萦纡一径通。","不向雷门操布鼓，要从人海见珠宫。","多言浪负三千牍，老梦都忘十八公。","珍重吾宗有成训，人间何似在山中。"]},{"t":"题西域木唐卿旌表孝义卷","f":"七言绝句","c":["桥梓天殊棣有华，良心初不间幽遐。","何年四海无旌表，尽化忠臣孝子家。"]},{"t":"琳宫词次安南王韵 其二","f":"七言绝句","c":["山中活计只餐霞，世事茫茫日自斜。","谪到玉堂无好况，夜深犹草侍中麻。"]},{"t":"织锦回文图","f":"七言绝句","c":["明珠金缕烂萦回，香玉连环剪不开。","不把肺肝都织出，将军惟识赵阳台。"]},{"t":"杜子美象","f":"七言绝句","c":["删后骚馀代有闻，集成惟许杜陵人。","凭谁寄语沿流者，流到江西不是春。"]},{"t":"赏心亭","f":"七言绝句","c":["赏心亭上双柏树，看我往来今十年。","柏树青青宛如昔，当时游子已华颠。"]},{"t":"牛背观书图","f":"七言绝句","c":["蒲鞯盘膝胜安舆，人讶形骸与世疏。","却笑徙居三十乘，恰如牛背一编书。"]},{"t":"丙吉问牛图","f":"七言绝句","c":["肥充列鼎健充车，厚养专为簿领驱。","千古清风梓人传，凭谁书继丙家图。"]},{"t":"和康里子山韵","f":"七言绝句","c":["洞深春早透兰芽，窗晓云香乱海霞。","万丈红尘飞不到，紫箫吹绽碧桃花。"]},{"t":"李陵台","f":"七言绝句","c":["李陵台下驻分台，红药金莲遍地开。","斜日一鞭三十里，北山飞雨逐人来。"]},{"t":"上都归口号","f":"七言绝句","c":["娇儿幼女逐山妻，争解行囊看赐衣。","颠倒海图裨短褐，可怜杜老北征归。"]},{"t":"信笔","f":"七言绝句","c":["造物知余素爱山，一官故调万山间。","山深民朴官无事，却为观山日不閒。"]},{"t":"冬夜即事","f":"七言绝句","c":["纸窗铺月白溶溶，炉火欺灯照室红。","万籁声沈人语定，好诗都在杳冥中。"]},{"t":"行县书所见","f":"七言绝句","c":["涨潦留泥粪稻畦，石渠分水灌麻池。","醉翁社散忘归路，行过柴门尚不知。"]},{"t":"谢祐之桃花折枝","f":"七言绝句","c":["天台不折一枝归，晴日明窗有所思。","流水乱山迷去路，案图无语立多时。"]},{"t":"令狐学士金莲图","f":"七言绝句","c":["九天光彩动金闺，辇路风香树影齐。","却笑汉家恩数薄，只教天禄待青藜。"]},{"t":"神山杂诗 其一","f":"七言绝句","c":["山留残雨湿拖云，竹引鲜飙细洒人。","诗思清如寒水玉，休教落纸恐沾尘。"]},{"t":"神山杂诗 其二","f":"七言绝句","c":["窗扉九夏镇长开，一榻无尘地有苔。","怪底山禽栖不稳，竹林风雨送凉来。"]},{"t":"次黎东山凤栖别墅韵 其一","f":"七言绝句","c":["风漪翠舞躬耕稻，云锦红酣手种花。","策杖寻君迷不得，有书声处是君家。"]},{"t":"次黎东山凤栖别墅韵 其二","f":"七言绝句","c":["七里原头营别业，三间堂下有东篱。","霜林不尽天如洗，都是山人未了诗。"]},{"t":"都门柳","f":"七言绝句","c":["都门四十里青青，几度迎人几送行。","老子有言来致柳，只烦相送莫相迎。"]},{"t":"书所见 其一","f":"七言绝句","c":["陵坡野菜绿如铺，肤受方期宥老榆。","菜少人多挑已尽，有榆从此尽无肤。"]},{"t":"书所见 其二","f":"七言绝句","c":["田园卖尽及儿孙，少壮流移老病存。","一段升平好图画，人间惟欠郑监门。"]},{"t":"夜次馆陶 其一","f":"七言绝句","c":["三老趋程不惮劳，船头坐看月轮高。","烟村渔火微茫外，一簇人家是馆陶。"]},{"t":"夜次馆陶 其二","f":"七言绝句","c":["浦云林雾郁苍苍，水面无风晚自凉。","今夜篷窗应不寐，计程三百是吾乡。"]},{"t":"林虑南楼","f":"七言绝句","c":["西山为我晓烟开，正尔癃钟造物哀。","更欲细看阴岭雾，老龙将雨出山来。"]},{"t":"题龙甫耕云堂","f":"七言绝句","c":["满山深锁白英英，不解为霖但可耕。","只恐无心忽飞去，野人何处望秋成。"]},{"t":"即事 其一","f":"七言绝句","c":["几家门系钓鱼船，一阵风香燎麦烟。","画出太平村落景，酒旗多在绿杨边。"]},{"t":"即事 其二","f":"七言绝句","c":["远浦客帆明冉冉，前村牧笛响呜呜。","园桑叶尽蚕成茧，庭树阴浓燕引雏。"]},{"t":"春日漫述","f":"七言绝句","c":["竹几蒲团懒最宜，不知花影隔窗移。","邻翁忽报小瓮熟，老子坐忘成坐驰。"]},{"t":"卧龙图","f":"七言绝句","c":["能办人间大有年，九渊谁遣抱珠眠。","等閒莫似隆中起，雨得西南蕞尔天。"]},{"t":"送张渊亮鍊师","f":"七言律诗","c":["杏园陈迹梦暄妍，马上相逢岂偶然。","每忆可人如隔世，不闻新句又经年。","花迎驿路飞红雨，香到朝山散紫烟。","王事游方归有日，迟君洹水白鸥前。"]},{"t":"和可行展省归过圭塘即席韵","f":"五言律诗","c":["墟里烟尘外，巾车日日来。","疏竹呈半塔，初日见三台。","酒每从邻贳，诗宁待雨催。","衰年怀易感，为我少迟回。"]},{"t":"四月二十七日庄之渊昆季治具至圭塘醉中赋奉寄一笑","f":"七言律诗","c":["拂水垂杨贴水荷，圭塘风景正清和。","岂能奇字□人问，深愧群贤载酒过。","花露坠红沾杖屦，松云凝翠遏弦歌。","也知节饮宜衰病，其奈乡情醉更多。"]},{"t":"秋露白酒熟卧闻槽声喜而得句可行当同赋也","f":"曲","c":["治曲辛勤夏竟秋，奇功今日遂全收。","日华煎露成真液，泉脉穿岩咽细流。","不忍泼醅?瓮面，且教留响在床头。","老怀磈磊行浇尽，三径黄花两玉舟。"]},{"t":"至正改元四月十三日戊子皇帝御龙舟幸护圣寺中书右丞臣帖木尔达实参知政事臣阿鲁臣有壬扈行乐三奏命右丞前特授平章政事参政进右丞臣有壬进左丞恳辞不允惶汗就列平章右丞曰今日游骋之盛恩遇之隆不可不纪也悚惧之馀为二十韵以献","f":"五言古诗","c":["宇宙承平日，邦畿壮丽乡。","宫中无暇逸，湖上暂翱翔。","凤辇重云降，龙舟万斛骧。","风霆随桂楫，日月运牙樯。","五卫分翚羽，千官列雁行。","长年花压帽，仙妓锦连航。","绒繂初徐引，銮旂渐远扬。","釐靬呈曼衍，僸佅递铿锵。","玉食传麟脯，冰壶出蔗浆。","鱼鸢知永跸，莺燕逐馀香。","夹岸金戈翊，弥空绣幕张。","汀回开瀚海，天近胜钱塘。","翠阁峨双岛，珠帘护两厢。","九霄披瑞霭，四表睹朝阳。","补助资游豫，登崇贵俊良。","不图推朽质，亦复被清光。","左辖纲维地，中书政事堂。","出谋惭不武，好学愿无荒。","喻水民堪畏，从桥策最长。","济川非所任，歌咏献岩廊。"]},{"t":"和虞伯生学士壁间韵","f":"五言律诗","c":["在公抱隐忧，出塞得奇观。","青山万马奔，龙门忽中断。","地平豁四维，天阔张一幔。","寄语鸣笳儿，休惊暮鸿散。"]},{"t":"寄赵秉彝","f":"七言律诗","c":["从军苦乐不难明，肯使毛锥负此生。","铁骑蹴云秋校猎，油幢敲雨夜论兵。","发应瘴疠催全白，诗为江山助益清。","诏下凯还今有日，阿绵闻已候门迎。"]},{"t":"七夕露坐感牛女事因成驳杂无实之言","f":"五言律诗","c":["别况经年惯，佳期此夕逢。","终天为伉俪，一水任西东。","人世非无鹊，羁窗渐有蛩。","鄜州共明月，应是忆衰翁。"]},{"t":"题赵干江楼风雨图","f":"七言古诗","c":["人间蕞尔东南陬，金陵李家无远谋。","词华欲继后庭曲，不见东风空上楼。","当时百事尚纤丽，况在画工专末技。","洪河乔岳昧平生，曲阑幽槛穷清致。","石头城下无重关，甲马营中有佳气。","九天飞坠曹将军，尽卷版图充上计。","小儿造化吁可怜，乾坤又到宣和年。","君王摇毫自涂抹，片纸落世人争传。","坐看南北又分裂，遂使两家同一天。","偶从断缣阅小景，慨念兴亡岂天定。","而今荡荡混一图，但少侬归理钓艇。"]},{"t":"次贾伯坚左司寄来韵二首 其一","f":"七言绝句","c":["酒来宛国注红香，鱼出凉亭荐雪肪。","多病浪仙都□此，空哦清句嚼冰霜。"]},{"t":"次贾伯坚左司寄来韵二首 其二","f":"七言绝句","c":["赐沾炰凤玉脂香，大笑轻身服雁肪。","华发侍臣归有日，鴐鹅先报一天霜。"]},{"t":"代书寄可行弟二首 其一","f":"七言绝句","c":["汉川云梦有租田，今岁应逢大有年。","约束诸僮公出纳，羡馀留粜杖头钱。"]},{"t":"代书寄可行弟二首 其二","f":"七言绝句","c":["文竹移栽只五根，来时无数长儿孙。","不因繁冗休轻剪，要使清阴过酒尊。"]},{"t":"出郭","f":"七言律诗","c":["万虑攻催雪满头，还乡才得纵遨游。","太行云尽青浮晓，洹水霜馀碧染秋。","渐老始知閒有味，此回真与世无求。","溪山好处鸱夷满，况有风流老郡侯。"]},{"t":"墨灶寺追和缑山先生韵","f":"七言律诗","c":["丹霞圆锁翠潭潭，仰面青天镜出函。","解组已能辞好爵，判山还欲署新衔。","冷传霜信风生谷，清透云根月满岩。","却忆瓈江旧林壑，几多烟雾护松杉。"]},{"t":"九日登凤宁山","f":"五言古诗","c":["亭亭凤宁山，形势若飞动。","胡为不飞去，仙真此抟控。","灵迹既不閟，烟霞遂增重。","城居见其图，清赏时入梦。","本朝事幽寻，霜风肃飞鞚。","适与佳节会，更与佳人共。","危亭搆两翼，飞云连画栋。","翠柏泻秋声，红树列清供。","遐观千里近，长歌百杯送。","洹流嗽其根，俯瞰清可弄。","陟降自忘疲，酬酢益豪纵。","牛山何用悲，兹方待鸣凤。"]},{"t":"圭塘独坐","f":"五言律诗","c":["我屋来西圃，轮蹄二里遥。","晚风收菡萏，秋雨长芭蕉。","有酒容开口，无官免折腰。","柴门莫坚闭，恐负野人招。"]},{"t":"新秋即事","f":"五言律诗","c":["莫蹋苍苔破，茨门昼亦关。","林风秋入树，波日晚摇山。","原野苍茫外，烟霏指顾间。","更须安一榻，月夜不须还。"]},{"t":"次和可行乡友具宴谩成","f":"七言律诗","c":["相望不隔一牛鸣，尊俎过从见至情。","荷露清涵芳酒气，松云寒遏艳歌声。","高车驷马初无意，白酒黄鸡旧有盟。","醉脱乌纱从露顶，绝胜前日缚尘缨。"]},{"t":"次和可行赴圭塘","f":"七言律诗","c":["卜筑何如履道坊，千红万绿浸银塘。","要回衰境为全盛，却使閒人号最忙。","活水清围容膝屋，新篁高出及肩墙。","烟霞遮断尘埃路，才觉山林白昼长。"]},{"t":"寄高元用","f":"七言绝句","c":["两鬓烟云朝共爨，一窗风雪夜同衾。","为君拈起当时语，应见相思万里心。"]}]};